(701, 'bore', 2, '/bɔː/', 'To inspire boredom in somebody.', '使厭煩、鑽孔', 'https://api.dictionaryapi.dev/media/pronunciations/en/bore-us.mp3', 1, '2026-06-01 14:48:14'),
(702, 'bored', 3, '/bɔːd/', 'Suffering from boredom; mildly annoyed and restless through having nothing to do', '感到厭煩的、無聊的', 'https://dictionaryapi.dev/bored', 1, '2026-06-01 14:48:14'),
(703, 'boring', 3, '/ˈbɔːɹɪŋ/', 'Causing boredom; unable to engage or hold the interest.', '乏味的、無聊的、令人厭煩的', 'https://api.dictionaryapi.dev/media/pronunciations/en/boring-us.mp3', 1, '2026-06-01 14:48:14'),
(704, 'born', 3, '/ˈbɔːn/', 'Having from birth (or as if from birth) a certain quality or character; innate; inherited.', '出生的、天生的', 'https://api.dictionaryapi.dev/media/pronunciations/en/born-us.mp3', 1, '2026-06-01 14:48:14'),
(705, 'borrow', 2, '/ˈbɔɹoʊ/', 'To receive (something) from somebody temporarily, expecting to return it.', '借、借入、借用', 'https://api.dictionaryapi.dev/media/pronunciations/en/borrow-us.mp3', 1, '2026-06-01 14:48:14'),
(706, 'boss', 1, '/bɑs/', 'A person who oversees and directs the work of others; a supervisor.', '老闆、上司、雇主', 'https://api.dictionaryapi.dev/media/pronunciations/en/boss-uk.mp3', 1, '2026-06-01 14:48:14'),
(707, 'botany', 1, '/-ɪ/', 'The scientific study of plants, a branch of biology. Typically those disciplines that involve the whole plant.', '植物學', 'https://api.dictionaryapi.dev/media/pronunciations/en/botany-us.mp3', 1, '2026-06-01 14:48:14'),
(708, 'both', 3, '/bəʊθ/', 'Each of the two, or of the two kinds.', '兩者的、雙方的', 'https://api.dictionaryapi.dev/media/pronunciations/en/both-us.mp3', 1, '2026-06-01 14:48:14'),
(709, 'both', 4, '/bəʊθ/', 'Each of the two, or of the two kinds.', '兩者都、既...又...', 'https://api.dictionaryapi.dev/media/pronunciations/en/both-us.mp3', 1, '2026-06-01 14:48:14'),
(710, 'bother', 1, '[ˈbɔðə(ɹ)]', 'Fuss, ado.', '麻煩、煩惱、打擾', 'https://api.dictionaryapi.dev/media/pronunciations/en/bother-uk.mp3', 1, '2026-06-01 14:48:14'),
(711, 'bother', 2, '[ˈbɔðə(ɹ)]', 'To annoy, to disturb, to irritate.', '打擾、麻煩、煩惱', 'https://api.dictionaryapi.dev/media/pronunciations/en/bother-uk.mp3', 1, '2026-06-01 14:48:14'),
(712, 'bottle', 1, '/ˈbɑ.təl/', 'A container, typically made of glass or plastic and having a tapered neck, used primarily for holding liquids.', '瓶子', 'https://api.dictionaryapi.dev/media/pronunciations/en/bottle-ca.mp3', 1, '2026-06-01 14:48:14'),
(713, 'bottle', 2, '/ˈbɑ.təl/', 'To seal (a liquid) into a bottle for later consumption. Also fig.', '裝瓶、把...裝進瓶裡', 'https://api.dictionaryapi.dev/media/pronunciations/en/bottle-ca.mp3', 1, '2026-06-01 14:48:14'),
(714, 'boulevard', 1, '/ˈbʊləvɑɹd/', 'A broad, well-paved and landscaped thoroughfare.', '林蔭大道、大街', 'https://api.dictionaryapi.dev/media/pronunciations/en/boulevard-ca.mp3', 1, '2026-06-01 14:48:14'),
(715, 'bounce', 1, '/baʊns/', 'A change of direction of motion after hitting the ground or an obstacle.', '彈回、跳動、活力', 'https://api.dictionaryapi.dev/media/pronunciations/en/bounce-us.mp3', 1, '2026-06-01 14:48:14'),
(716, 'bounce', 2, '/baʊns/', 'To change the direction of motion after hitting an obstacle.', '彈起、反彈、使跳動', 'https://api.dictionaryapi.dev/media/pronunciations/en/bounce-us.mp3', 1, '2026-06-01 14:48:14'),
(717, 'bound', 3, '/ˈbaʊnd/', '(with infinitive) Obliged (to).', '被束縛的、受限制的、必然的、準備前往...的', 'https://api.dictionaryapi.dev/media/pronunciations/en/bound-us.mp3', 1, '2026-06-01 14:48:14'),
(718, 'bow', 1, '/bəʊ/', 'A weapon made of a curved piece of wood or other flexible material whose ends are connected by a string, used for shooting arrows.', '弓、蝴蝶結、琴弓、船頭', 'https://api.dictionaryapi.dev/media/pronunciations/en/bow-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(719, 'bow', 2, '/bəʊ/', 'To play music on (a stringed) instrument using a bow.', '彎腰、鞠躬、屈服', 'https://api.dictionaryapi.dev/media/pronunciations/en/bow-1-uk.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(720, 'bowl', 1, '/bəʊɫ/', 'A roughly hemispherical container used to hold, mix or present food, such as salad, fruit or soup, or other items.', '碗、大木球', 'https://api.dictionaryapi.dev/media/pronunciations/en/bowl-us.mp3', 1, '2026-06-01 14:48:14'),
(721, 'bowling', 1, '', 'A game played by rolling a ball down an alley and trying to knock over a triangular group of ten pins; ten-pin bowling/five-pin bowling', '保齡球運動', 'https://api.dictionaryapi.dev/media/pronunciations/en/bowling-au.mp3', 1, '2026-06-01 14:48:14'),
(722, 'box', 1, '', 'Senses relating to a three-dimensional object or space.', '盒子、箱子、包廂', 'https://api.dictionaryapi.dev/media/pronunciations/en/box-au.mp3', 1, '2026-06-01 14:48:14'),
(723, 'box', 2, '', 'To place inside a box; to pack in one or more boxes.', '裝箱、拳擊', 'https://api.dictionaryapi.dev/media/pronunciations/en/box-au.mp3', 1, '2026-06-01 14:48:14'),
(724, 'boxing', 1, '/ˈbɒksɪŋ/', 'A sport where two opponents punch each other with gloved fists, the object being to score more points by the end of the match or by knockout, or technical knockout.', '拳擊', 'https://dictionaryapi.dev/boxing', 1, '2026-06-01 14:48:14'),
(725, 'boy', 1, '/bɔːə/', 'A young male.', '男孩、少年', 'https://api.dictionaryapi.dev/media/pronunciations/en/boy-us.mp3', 1, '2026-06-01 14:48:14'),
(726, 'boycott', 2, '/ˈbɔɪkɒt/', 'To abstain, either as an individual or a group, from using, buying, or dealing with someone or some organization as an expression of protest.', '聯合抵制、拒絕購買', 'https://dictionaryapi.dev/boycott', 1, '2026-06-01 14:48:14'),
(727, 'brace', 1, '/bɹeɪs/', 'Armor for the arm; vambrace.', '支架、托架、大括號、護具', 'https://api.dictionaryapi.dev/media/pronunciations/en/brace-uk.mp3', 1, '2026-06-01 14:48:14'),
(728, 'brain', 1, '/bɹeɪn/', 'The control center of the central nervous system of an animal located in the skull which is responsible for perception, cognition, attention, memory, emotion, and action.', '大腦、智力、腦髓', 'https://api.dictionaryapi.dev/media/pronunciations/en/brain-uk.mp3', 1, '2026-06-01 14:48:14'),
(729, 'brake', 1, '/bɹeɪk/', 'A fern; bracken.', '煞車、車閘', 'https://api.dictionaryapi.dev/media/pronunciations/en/brake-us.mp3', 1, '2026-06-01 14:48:14'),
(730, 'brake', 2, '/bɹeɪk/', 'A fern; bracken.', '煞車、制動', 'https://api.dictionaryapi.dev/media/pronunciations/en/brake-us.mp3', 1, '2026-06-01 14:48:14'),
(731, 'branch', 1, '/bɹæntʃ/', 'The woody part of a tree arising from the trunk and usually dividing.', '樹枝、分公司、分支、支流', 'https://api.dictionaryapi.dev/media/pronunciations/en/branch-us.mp3', 1, '2026-06-01 14:48:14'),
(732, 'branch', 2, '/bɹæntʃ/', 'To arise from the trunk or a larger branch of a tree.', '分支、分支出來', 'https://api.dictionaryapi.dev/media/pronunciations/en/branch-us.mp3', 1, '2026-06-01 14:48:14'),
(733, 'brand', 1, '/bɹand/', 'A conflagration; a flame.', '商標、品牌、烙印', 'https://api.dictionaryapi.dev/media/pronunciations/en/brand-us.mp3', 1, '2026-06-01 14:48:14'),
(734, 'brave', 3, '/bɹeɪv/', 'Strong in the face of fear; courageous.', '勇敢的、英勇的', 'https://api.dictionaryapi.dev/media/pronunciations/en/brave-us.mp3', 1, '2026-06-01 14:48:14'),
(735, 'bravery', 1, '/ˈbɹeɪvəɹi/', '(usually uncountable) Being brave, courageousness.', '勇敢、英勇', 'https://api.dictionaryapi.dev/media/pronunciations/en/bravery-us.mp3', 1, '2026-06-01 14:48:14'),
(736, 'breach', 2, '[bɹiːtʃ]', 'To make a breach in.', '破壞、違反、突破', 'https://api.dictionaryapi.dev/media/pronunciations/en/breach-us.mp3', 1, '2026-06-01 14:48:14'),
(737, 'bread', 1, '/bɹeːd/', 'A foodstuff made by baking dough made from cereals.', '麵包、生計', 'https://api.dictionaryapi.dev/media/pronunciations/en/bread-uk.mp3', 1, '2026-06-01 14:48:14'),
(738, 'break', 1, '/bɹeɪk/', 'An instance of breaking something into two or more pieces.', '裂口、休息、中斷', 'https://api.dictionaryapi.dev/media/pronunciations/en/break-us.mp3', 1, '2026-06-01 14:48:14'),
(739, 'break', 2, '/bɹeɪk/', 'To separate into two or more pieces, to fracture or crack, by a process that cannot easily be reversed for reassembly.', '打破、折斷、違反、打破（紀錄）', 'https://api.dictionaryapi.dev/media/pronunciations/en/break-us.mp3', 1, '2026-06-01 14:48:14'),
(740, 'break-up', 1, '', 'The act of breaking up; disintegration or division.', '分手、中斷、瓦解', 'https://dictionaryapi.dev/break-up', 1, '2026-06-01 14:48:14'),
(741, 'breakdown', 1, '/ˈbɹeɪkdaʊn/', 'A failure, particularly mechanical; something that has failed', '故障、崩潰、衰竭、細目分類', 'https://dictionaryapi.dev/breakdown', 1, '2026-06-01 14:48:14'),
(742, 'breakfast', 1, '/ˈbɹɛkfəst/', 'The first meal of the day, usually eaten in the morning.', '早餐', 'https://api.dictionaryapi.dev/media/pronunciations/en/breakfast-uk.mp3', 1, '2026-06-01 14:48:14'),
(743, 'breakfast', 2, '/ˈbɹɛkfəst/', 'To eat the morning meal.', '吃早餐', 'https://api.dictionaryapi.dev/media/pronunciations/en/breakfast-uk.mp3', 1, '2026-06-01 14:48:14'),
(744, 'breast', 1, '/bɹɛst/', 'Either of the two organs on the front of a female human\'s chest, which contain the mammary glands; also the analogous organs in males.', '乳房、胸部', 'https://api.dictionaryapi.dev/media/pronunciations/en/breast-us.mp3', 1, '2026-06-01 14:48:14'),
(745, 'breath', 1, '/bɹɛθ/', 'The act or process of breathing.', '呼吸、微風', 'https://api.dictionaryapi.dev/media/pronunciations/en/breath-us.mp3', 1, '2026-06-01 14:48:14'),
(746, 'breathe', 2, '/bɹiːð/', 'To draw air into (inhale), and expel air from (exhale), the lungs in order to extract oxygen and excrete waste gases.', '呼吸、吸入', 'https://api.dictionaryapi.dev/media/pronunciations/en/breathe-us.mp3', 1, '2026-06-01 14:48:14'),
(747, 'breathtaking', 3, '/ˈbɹɛθˌteɪ.kɪŋ/', 'Stunningly beautiful; amazing', '驚人的、極美的、令人屏息的', 'https://api.dictionaryapi.dev/media/pronunciations/en/breathtaking-us.mp3', 1, '2026-06-01 14:48:14'),
(748, 'breed', 1, '/bɹiːd/', 'All animals or plants of the same species or subspecies.', '品種、種類', 'https://api.dictionaryapi.dev/media/pronunciations/en/breed-us.mp3', 1, '2026-06-01 14:48:14'),
(749, 'breed', 2, '/bɹiːd/', 'To produce offspring sexually; to bear young.', '繁殖、飼養、培育、引起', 'https://api.dictionaryapi.dev/media/pronunciations/en/breed-us.mp3', 1, '2026-06-01 14:48:14'),
(750, 'breeder', 1, '/ˈbɹiːdə(ɹ)/', 'A person who breeds plants or animals (professionally).', '飼養員、育種家', 'https://api.dictionaryapi.dev/media/pronunciations/en/breeder-au.mp3', 1, '2026-06-01 14:48:14'),
(751, 'breeze', 1, '/bɹiːz/', 'A light, gentle wind.', '微風、輕而易舉的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/breeze-au.mp3', 1, '2026-06-01 14:48:14'),
(752, 'breeze', 2, '/bɹiːz/', '(usually with along) To move casually, in a carefree manner.', '吹著微風、輕鬆地走', 'https://api.dictionaryapi.dev/media/pronunciations/en/breeze-au.mp3', 1, '2026-06-01 14:48:14'),
(753, 'brew', 2, '/bɹuː/', 'To make tea or coffee by mixing tea leaves or coffee beans with hot water.', '釀造、泡（茶、咖啡）、醞釀', 'https://api.dictionaryapi.dev/media/pronunciations/en/brew-1-us.mp3', 1, '2026-06-01 14:48:14'),
(754, 'brick', 1, '/bɹɪk/', 'A hardened rectangular block of mud, clay etc., used for building.', '磚、磚塊', 'https://api.dictionaryapi.dev/media/pronunciations/en/brick-us.mp3', 1, '2026-06-01 14:48:14'),
(755, 'bride', 1, '/bɹaɪd/', 'A woman in the context of her own wedding; one who is going to marry or has just been married.', '新娘', 'https://dictionaryapi.dev/bride', 1, '2026-06-01 14:48:14'),
