(757, 'bridge', 1, '/bɹɪd͡ʒ/', 'A construction or natural feature that spans a divide.', '橋、橋牌、鼻樑', 'https://api.dictionaryapi.dev/media/pronunciations/en/bridge-us.mp3', 1, '2026-06-01 14:48:14'),
(758, 'bridge', 2, '/bɹɪd͡ʒ/', 'To be or make a bridge over something.', '架橋於、渡過、彌合', 'https://api.dictionaryapi.dev/media/pronunciations/en/bridge-us.mp3', 1, '2026-06-01 14:48:14'),
(759, 'brief', 1, '/bɹiːf/', 'A writ summoning one to answer to any action.', '摘要、簡報', 'https://api.dictionaryapi.dev/media/pronunciations/en/brief-us.mp3', 1, '2026-06-01 14:48:14'),
(760, 'brief', 2, '/bɹiːf/', 'To summarize a recent development to some person with decision-making power.', '向...作簡報、摘要', 'https://api.dictionaryapi.dev/media/pronunciations/en/brief-us.mp3', 1, '2026-06-01 14:48:14'),
(761, 'brief', 3, '/bɹiːf/', 'Of short duration; happening quickly.', '簡短的、短暫的', 'https://api.dictionaryapi.dev/media/pronunciations/en/brief-us.mp3', 1, '2026-06-01 14:48:14'),
(762, 'briefcase', 1, '/ˈbɹiːfˌkeɪs/', 'A case used for carrying documents, especially for business.', '公事包', 'https://dictionaryapi.dev/briefcase', 1, '2026-06-01 14:48:14'),
(763, 'briefmg', 1, '', 'N/A', '簡報、簡要指示', NULL, 1, '2026-06-01 14:48:14'),
(764, 'brigade', 1, '/bɹɪˈɡeɪd/', 'A group of people organized for a common purpose.', '旅、隊、組', 'https://api.dictionaryapi.dev/media/pronunciations/en/brigade-us.mp3', 1, '2026-06-01 14:48:14'),
(765, 'bright', 3, '/bɹaɪt/', 'Visually dazzling; luminous, lucent, clear, radiant; not dark.', '明亮的、聰明的、鮮豔的', 'https://api.dictionaryapi.dev/media/pronunciations/en/bright-us.mp3', 1, '2026-06-01 14:48:14'),
(766, 'brighten', 2, '/ˈbɹaɪtən/', 'To make bright or brighter in color.', '使變亮、使開朗、使輝煌', 'https://api.dictionaryapi.dev/media/pronunciations/en/brighten-uk.mp3', 1, '2026-06-01 14:48:14'),
(767, 'brilliant', 3, '/ˈbɹɪljənt/', 'Shining brightly.', '輝煌的、傑出的、才華橫溢的', 'https://api.dictionaryapi.dev/media/pronunciations/en/brilliant-us.mp3', 1, '2026-06-01 14:48:14'),
(768, 'bring', 2, '/ˈbɹɪŋ/', '(ditransitive) To transport toward somebody/somewhere.', '帶來、拿來、引起', 'https://api.dictionaryapi.dev/media/pronunciations/en/bring-uk.mp3', 1, '2026-06-01 14:48:14'),
(769, 'brisk', 3, '/bɹɪsk/', 'Full of liveliness and activity; characterized by quickness of motion or action', '敏捷的、活潑的、清新的', 'https://dictionaryapi.dev/brisk', 1, '2026-06-01 14:48:14'),
(770, 'Briton', 1, '', 'N/A', '英國人、不列顛人', NULL, 1, '2026-06-01 14:48:14'),
(771, 'broad', 3, '/bɹɑd/', 'Wide in extent or scope.', '寬的、遼闊的、廣泛的', 'https://api.dictionaryapi.dev/media/pronunciations/en/broad-1-us.mp3', 1, '2026-06-01 14:48:14'),
(772, 'broadcast', 1, '/ˈbɹɑdkæst/', 'A transmission of a radio or television programme intended to be received by anyone with a receiver.', '廣播、電視節目', 'https://api.dictionaryapi.dev/media/pronunciations/en/broadcast-us.mp3', 1, '2026-06-01 14:48:14'),
(773, 'broadcast', 2, '/ˈbɹɑdkæst/', 'To transmit a message or signal through radio waves or electronic means.', '廣播、播放、播送', 'https://api.dictionaryapi.dev/media/pronunciations/en/broadcast-us.mp3', 1, '2026-06-01 14:48:14'),
(774, 'broaden', 2, '', 'To make broad or broader.', '變寬、擴大、加寬', 'https://dictionaryapi.dev/broaden', 1, '2026-06-01 14:48:14'),
(775, 'brochure', 1, '/ˈbɹəʊ.ʃə(ɹ)/', 'A booklet of printed informational matter, like a pamphlet, often for promotional purposes.', '小冊子、指南', 'https://api.dictionaryapi.dev/media/pronunciations/en/brochure-us.mp3', 1, '2026-06-01 14:48:14'),
