(1664, 'decrease', 1, '', 'An amount by which a quantity is decreased.', '減少、減少量', 'https://api.dictionaryapi.dev/media/pronunciations/en/decrease-us.mp3', 1, '2026-06-01 14:48:14'),
(1665, 'decrease', 2, '', 'Of a quantity, to become smaller.', '減少、降低', 'https://api.dictionaryapi.dev/media/pronunciations/en/decrease-us.mp3', 1, '2026-06-01 14:48:14'),
(1666, 'decree', 1, '/dɪˈkɹiː/', 'An edict or law.', '法令、政令、判決', 'https://api.dictionaryapi.dev/media/pronunciations/en/decree-uk.mp3', 1, '2026-06-01 14:48:14'),
(1667, 'decree', 2, '/dɪˈkɹiː/', 'To command by a decree.', '頒布法令、判決', 'https://api.dictionaryapi.dev/media/pronunciations/en/decree-uk.mp3', 1, '2026-06-01 14:48:14'),
(1668, 'dedicate', 2, '/ˈdɛdɪkeɪt/', 'To set apart for a deity or for religious purposes; consecrate.', '奉獻、致力於、題獻', 'https://api.dictionaryapi.dev/media/pronunciations/en/dedicate-uk.mp3', 1, '2026-06-01 14:48:14'),
(1669, 'deduction', 1, '/dɪˈdʊkʃən/', 'That which is deducted; that which is subtracted or removed', '扣除、推論、演繹法', 'https://api.dictionaryapi.dev/media/pronunciations/en/deduction-us.mp3', 1, '2026-06-01 14:48:14'),
(1670, 'deed', 1, '/diːd/', 'An action or act; something that is done.', '行為、契據、證書', 'https://api.dictionaryapi.dev/media/pronunciations/en/deed-us.mp3', 1, '2026-06-01 14:48:14'),
(1671, 'deem', 2, '', 'To judge, to pass judgment on; to doom, to sentence.', '認為、視為', 'https://api.dictionaryapi.dev/media/pronunciations/en/deem-au.mp3', 1, '2026-06-01 14:48:14'),
(1672, 'deep', 3, '/diːp/', '(of a physical distance) Extending far away from a point of reference, especially downwards.', '深的、深奧的、濃厚的', 'https://api.dictionaryapi.dev/media/pronunciations/en/deep-au.mp3', 1, '2026-06-01 14:48:14'),
(1673, 'deep', 4, '/diːp/', 'Deeply.', '深深地、深入地', 'https://api.dictionaryapi.dev/media/pronunciations/en/deep-au.mp3', 1, '2026-06-01 14:48:14'),
(1674, 'deepen', 2, '/ˈdiːpən/', 'To make deep or deeper', '加深、變深、變劇烈', 'https://dictionaryapi.dev/deepen', 1, '2026-06-01 14:48:14'),
(1675, 'deer', 1, '/diːɹ/', 'A ruminant mammal with antlers and hooves of the family Cervidae, or one of several similar animals from related families of the order Artiodactyla', '鹿', 'https://api.dictionaryapi.dev/media/pronunciations/en/deer-us.mp3', 1, '2026-06-01 14:48:14'),
(1676, 'defeat', 1, '/dɪˈfiːt/', 'To overcome in battle or contest.', '失敗、戰敗、挫敗', 'https://api.dictionaryapi.dev/media/pronunciations/en/defeat-us.mp3', 1, '2026-06-01 14:48:14'),
(1677, 'defeat', 2, '/dɪˈfiːt/', 'To overcome in battle or contest.', '擊敗、戰勝、使挫敗', 'https://api.dictionaryapi.dev/media/pronunciations/en/defeat-us.mp3', 1, '2026-06-01 14:48:14'),
(1678, 'defect', 1, '', 'A fault or malfunction.', '缺點、瑕疵、缺陷', 'https://api.dictionaryapi.dev/media/pronunciations/en/defect-uk.mp3', 1, '2026-06-01 14:48:14'),
(1679, 'defend', 2, '/dɪˈfɛnd/', 'To ward off attacks against; to fight to protect; to guard.', '防守、辯護、保衛', 'https://api.dictionaryapi.dev/media/pronunciations/en/defend-us.mp3', 1, '2026-06-01 14:48:14'),
(1680, 'defense', 1, '/dɪˈfɛns/', 'The action of defending or protecting from attack, danger, or injury.', '防禦、防衛、辯護', 'https://api.dictionaryapi.dev/media/pronunciations/en/defense-us.mp3', 1, '2026-06-01 14:48:14'),
(1681, 'defensive', 3, '', 'Intended for defence; protective.', '防禦性的、自衛的', 'https://api.dictionaryapi.dev/media/pronunciations/en/defensive-au.mp3', 1, '2026-06-01 14:48:14'),
(1682, 'deficiency', 1, '/dɪˈfɪʃənsi/', 'Inadequacy or incompleteness.', '缺乏、不足、缺陷', 'https://dictionaryapi.dev/deficiency', 1, '2026-06-01 14:48:14'),
(1683, 'deficit', 1, '/ˈdɛfɪsɪt/', 'Deficiency in amount or quality; a falling short; lack.', '赤字、虧損', 'https://dictionaryapi.dev/deficit', 1, '2026-06-01 14:48:14'),
(1684, 'define', 2, '/dɪˈfaɪn/', 'To determine with precision; to mark out with distinctness; to ascertain or exhibit clearly.', '下定義、限定、解釋', 'https://api.dictionaryapi.dev/media/pronunciations/en/define-us.mp3', 1, '2026-06-01 14:48:14'),
(1685, 'definite', 3, '/ˈdɛfɪnɪt/', 'Having distinct limits.', '明確的、肯定的、限定的', 'https://api.dictionaryapi.dev/media/pronunciations/en/definite-us.mp3', 1, '2026-06-01 14:48:14'),
(1686, 'defy', 2, '/dɪˈfaɪ/', 'To challenge (someone) or brave (a hazard or opposition).', '違抗、反抗、公然藐視', 'https://api.dictionaryapi.dev/media/pronunciations/en/defy-us.mp3', 1, '2026-06-01 14:48:14'),
(1687, 'degree', 1, '/dɪˈɡɹiː/', 'A stage of proficiency or qualification in a course of study, now especially an award bestowed by a university or, in some countries, a college, as a certification of academic achievement. (In the United States, can include secondary schools.)', '程度、度數、學位', 'https://api.dictionaryapi.dev/media/pronunciations/en/degree-uk.mp3', 1, '2026-06-01 14:48:14'),
(1688, 'delay', 1, '/dɪˈleɪ/', 'A period of time before an event occurs; the act of delaying; procrastination; lingering inactivity.', '延誤、延期', 'https://api.dictionaryapi.dev/media/pronunciations/en/delay-1-us.mp3', 1, '2026-06-01 14:48:14'),
(1689, 'delay', 2, '/dɪˈleɪ/', 'To put off until a later time; to defer.', '推遲、耽擱、延誤', 'https://api.dictionaryapi.dev/media/pronunciations/en/delay-1-us.mp3', 1, '2026-06-01 14:48:14'),
(1690, 'delegate', 2, '', 'To authorize someone to be a delegate', '委派...為代表、授權', 'https://dictionaryapi.dev/delegate', 1, '2026-06-01 14:48:14'),
(1691, 'delegation', 1, '/dɛlɪˈɡeɪʃən/', 'An act of delegating.', '代表團、委派', 'https://dictionaryapi.dev/delegation', 1, '2026-06-01 14:48:14'),
(1692, 'deliberately', 4, '/dəˈlɪb(ə)ɹətli/', 'Intentionally, or after deliberation; not accidentally.', '故意地、蓄意地、審慎地', 'https://api.dictionaryapi.dev/media/pronunciations/en/deliberately-us.mp3', 1, '2026-06-01 14:48:14'),
(1693, 'deliberation', 1, '/dɪˌlɪbəˈɹeɪʃən/', 'The act of deliberating, or of weighing and examining the reasons for and against a choice or measure; careful consideration; mature reflection.', '深思熟慮、審議、從容', 'https://dictionaryapi.dev/deliberation', 1, '2026-06-01 14:48:14'),
(1694, 'delicacy', 1, '/ˈdɛlɪkəsi/', 'The quality of being delicate.', '佳餚、精緻、脆弱', 'https://api.dictionaryapi.dev/media/pronunciations/en/delicacy-us.mp3', 1, '2026-06-01 14:48:14'),
(1695, 'delicate', 3, '/ˈdɛlɪkət/', 'Easily damaged or requiring careful handling.', '精緻的、脆弱的、微妙的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delicate-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(1696, 'delicious', 3, '/dɪˈlɪʃəs/', 'Pleasing to taste; tasty.', '美味的、令人愉快的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delicious-us.mp3', 1, '2026-06-01 14:48:14'),
(1697, 'delight', 1, '/dəˈlaɪt/', 'Joy; pleasure.', '欣喜、快樂、令人高興的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/delight-us.mp3', 1, '2026-06-01 14:48:14'),
(1698, 'delight', 2, '/dəˈlaɪt/', 'To give delight to; to affect with great pleasure; to please highly.', '使高興、使欣喜', 'https://api.dictionaryapi.dev/media/pronunciations/en/delight-us.mp3', 1, '2026-06-01 14:48:14'),
(1699, 'delightful', 3, '[dəˈlaɪ̯t̚.fəɫ]', 'Pleasant; pleasing, bringing enjoyment, satisfaction, or pleasure.', '令人愉快的、討人喜歡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delightful-us.mp3', 1, '2026-06-01 14:48:14'),
(1700, 'delinquent', 3, '/dɪˈlɪŋkwənt/', 'Late or failing to pay a debt or other financial obligation, like a mortgage or loan.', '違法的、拖欠的、有過失的', 'https://api.dictionaryapi.dev/media/pronunciations/en/delinquent-us.mp3', 1, '2026-06-01 14:48:14'),
(1701, 'deliver', 2, '/dɪˈlɪvə(ɹ)/', 'To set free from restraint or danger.', '遞送、交付、發表、接生', 'https://api.dictionaryapi.dev/media/pronunciations/en/deliver-us.mp3', 1, '2026-06-01 14:48:14'),
(1702, 'delivery', 1, '/dɪˈlɪv(ə)ɹi/', 'The act of conveying something.', '遞送、交付、分娩、演講', 'https://api.dictionaryapi.dev/media/pronunciations/en/delivery-au.mp3', 1, '2026-06-01 14:48:14'),
(1703, 'demand', 1, '/dɪˈmɑːnd/', 'The desire to purchase goods and services.', '需求、要求', 'https://api.dictionaryapi.dev/media/pronunciations/en/demand-us.mp3', 1, '2026-06-01 14:48:14'),
(1704, 'demand', 2, '/dɪˈmɑːnd/', 'To request forcefully.', '要求、強烈需要', 'https://api.dictionaryapi.dev/media/pronunciations/en/demand-us.mp3', 1, '2026-06-01 14:48:14'),
(1705, 'demanding', 3, '/dɪˈmɑːndɪŋ/', 'Requiring much endurance, strength, or patience.', '要求高的、費力的、苛求的', 'https://dictionaryapi.dev/demanding', 1, '2026-06-01 14:48:14'),
(1706, 'demo', 1, '/ˈdɛm.əʊ/', 'A demonstration or visual explanation.', '演示、樣本、民主黨人', 'https://api.dictionaryapi.dev/media/pronunciations/en/demo-uk.mp3', 1, '2026-06-01 14:48:14'),
(1707, 'democracy', 1, '/dɪˈmɒkɹəsi/', 'Rule by the people, especially as a form of government; either directly or through elected representatives (representative democracy).', '民主、民主政治、民主國家', 'https://dictionaryapi.dev/democracy', 1, '2026-06-01 14:48:14'),
(1708, 'democrat', 1, '/ˈdɛməkɹæt/', 'A supporter of democracy; an advocate of democratic politics (originally as opposed to the aristocrats in Revolutionary France).', '民主主義者、民主黨人', 'https://dictionaryapi.dev/democrat', 1, '2026-06-01 14:48:14'),
(1709, 'democratic', 3, '/dɛməˈkɹætɪk/', 'Pertaining to democracy; favoring democracy, or constructed upon the principle of government by the people.', '民主的、民主政體的', 'https://api.dictionaryapi.dev/media/pronunciations/en/democratic-us.mp3', 1, '2026-06-01 14:48:14'),
(1710, 'demon', 1, '/ˈdiː.mən/', 'An evil supernatural spirit.', '惡魔、魔鬼、精力過人的人', 'https://api.dictionaryapi.dev/media/pronunciations/en/demon-uk.mp3', 1, '2026-06-01 14:48:14'),
(1711, 'demonstrate', 2, '/ˈdɛmənstɹeɪt/', 'To show how to use (something).', '論證、證明、示範、示威', 'https://api.dictionaryapi.dev/media/pronunciations/en/demonstrate-us.mp3', 1, '2026-06-01 14:48:14'),
(1712, 'demonstration', 1, '/dɛmənˈstɹeɪʃən/', 'The act of demonstrating; showing or explaining something.', '示威運動、實作示範、論證', 'https://api.dictionaryapi.dev/media/pronunciations/en/demonstration-us.mp3', 1, '2026-06-01 14:48:14'),
(1713, 'denial', 1, '/dɪˈnaɪ.əl/', 'The negation in logic.', '否認、拒絕、否定', 'https://api.dictionaryapi.dev/media/pronunciations/en/denial-us.mp3', 1, '2026-06-01 14:48:14'),
(1714, 'denomination', 1, '/dɪˌnɒmɪˈneɪʃən/', 'The act of naming or designating.', '面額、教派、名稱', 'https://dictionaryapi.dev/denomination', 1, '2026-06-01 14:48:14'),
(1715, 'denote', 2, '/dɪˈnəʊt/', 'To indicate; to mark.', '表示、意味著、是...的標誌', 'https://api.dictionaryapi.dev/media/pronunciations/en/denote-us.mp3', 1, '2026-06-01 14:48:14'),
(1716, 'denounce', 2, '/diˈnaʊns/', 'To make known in a formal manner; to proclaim; to announce; to declare.', '譴責、指責、告發', 'https://api.dictionaryapi.dev/media/pronunciations/en/denounce-au.mp3', 1, '2026-06-01 14:48:14'),
(1717, 'dense', 3, '/dɛns/', 'Having relatively high density.', '稠密的、密集的、愚笨的', 'https://api.dictionaryapi.dev/media/pronunciations/en/dense-us.mp3', 1, '2026-06-01 14:48:14'),
(1718, 'dental', 1, '/ˈdɛntl̩/', 'Cleaning and polishing of an animal\'s teeth.', '牙科記錄、牙齒診斷', 'https://dictionaryapi.dev/dental', 1, '2026-06-01 14:48:14'),
(1719, 'dental', 3, '/ˈdɛntl̩/', 'Of or concerning the teeth, as in dental care.', '牙科的、牙齒的', 'https://dictionaryapi.dev/dental', 1, '2026-06-01 14:48:14'),
(1720, 'dentist', 1, '/ˈdɛntɪst/', 'A medical doctor who specializes in dentistry.', '牙醫', 'https://api.dictionaryapi.dev/media/pronunciations/en/dentist-us.mp3', 1, '2026-06-01 14:48:14'),
(1721, 'deny', 2, '/dɪˈnaɪ/', 'To disallow or reject.', '否認、拒絕給予', 'https://api.dictionaryapi.dev/media/pronunciations/en/deny-us.mp3', 1, '2026-06-01 14:48:14'),
(1722, 'depart', 2, '/dɪˈpɑːt/', 'To leave.', '出發、離開、背離', 'https://api.dictionaryapi.dev/media/pronunciations/en/depart-us.mp3', 1, '2026-06-01 14:48:14'),
(1723, 'departure', 1, '/dɪˈpɑː(ɹ)tjə(ɹ)/', 'The act of departing or something that has departed.', '出發、離開、逝世', 'https://api.dictionaryapi.dev/media/pronunciations/en/departure-uk.mp3', 1, '2026-06-01 14:48:14'),
(1724, 'depend', 2, '/dɪˈpɛnd/', '(followed by on or upon, formerly also by of) To be contingent or conditioned; to have something as a necessary condition; to hinge on.', '取決於、依靠、信任', 'https://api.dictionaryapi.dev/media/pronunciations/en/depend-us.mp3', 1, '2026-06-01 14:48:14'),
(1725, 'dependent', 3, '/dɪˈpɛndənt/', 'Relying upon; depending upon.', '依賴的、取決於...的', 'https://api.dictionaryapi.dev/media/pronunciations/en/dependent-us.mp3', 1, '2026-06-01 14:48:14'),
(1726, 'depict', 2, '/dɪˈpɪkt/', 'To render a representation of something, using words, sounds, images, or other means.', '描繪、描述、畫', 'https://api.dictionaryapi.dev/media/pronunciations/en/depict-us.mp3', 1, '2026-06-01 14:48:14'),
(1727, 'deplete', 2, '/dɪˈpliːt/', 'To empty or unload, as the vessels of the human system, by bloodletting or by medicine.', '耗盡、使空虛、大幅減少', 'https://api.dictionaryapi.dev/media/pronunciations/en/deplete-us.mp3', 1, '2026-06-01 14:48:14'),
(1728, 'deploy', 1, '/dɪˈplɔɪ/', 'Deployment', '部署、配置', 'https://dictionaryapi.dev/deploy', 1, '2026-06-01 14:48:14'),
(1729, 'deploy', 2, '/dɪˈplɔɪ/', 'To prepare and arrange (usually military unit or units) for use.', '部署、調動、利用', 'https://dictionaryapi.dev/deploy', 1, '2026-06-01 14:48:14'),
(1730, 'deport', 2, '/dɪˈpɔːt/', 'To comport (oneself); to behave.', '驅逐出境、驅逐', 'https://api.dictionaryapi.dev/media/pronunciations/en/deport-us.mp3', 1, '2026-06-01 14:48:14'),
(1731, 'deposit', 1, '/dɪˈpɒzɪt/', 'Sediment or rock that is not native to its present location or is different from the surrounding material. Sometimes refers to ore or gems.', '存款、押金、沉澱物', 'https://api.dictionaryapi.dev/media/pronunciations/en/deposit-us.mp3', 1, '2026-06-01 14:48:14'),
(1732, 'deposit', 2, '/dɪˈpɒzɪt/', 'To lay down; to place; to put.', '存放、寄託、儲蓄、沉澱', 'https://api.dictionaryapi.dev/media/pronunciations/en/deposit-us.mp3', 1, '2026-06-01 14:48:14'),
(1733, 'depreciate', 2, '/dɪˈpɹiːʃɪeɪt/', 'To lessen in price or estimated value; to lower the worth of.', '貶值、輕視、折舊', 'https://api.dictionaryapi.dev/media/pronunciations/en/depreciate-uk.mp3', 1, '2026-06-01 14:48:14'),
(1734, 'depress', 2, '/dɪˈpɹɛs/', 'To press down.', '使沮喪、使蕭條、壓低', 'https://dictionaryapi.dev/depress', 1, '2026-06-01 14:48:14'),
(1735, 'depression', 1, '/dɪˈpɹɛʃən/', 'In psychotherapy and psychiatry, a state of mind producing serious, long-term lowering of enjoyment of life or inability to visualize a happy future.', '憂鬱症、沮喪、經濟蕭條', 'https://api.dictionaryapi.dev/media/pronunciations/en/depression-us.mp3', 1, '2026-06-01 14:48:14'),
(1736, 'deprive', 2, '/dɪˈpɹaɪv/', 'To take something away from (someone) and keep it away; to deny someone something.', '剝奪、使喪失', 'https://dictionaryapi.dev/deprive', 1, '2026-06-01 14:48:14'),
(1737, 'depth', 1, '/dɛpθ/', 'The vertical distance below a surface; the degree to which something is deep', '深度、深刻、深處', 'https://api.dictionaryapi.dev/media/pronunciations/en/depth-us.mp3', 1, '2026-06-01 14:48:14'),
(1738, 'descendant', 1, '/dɪˈsɛndənt/', 'One who is the progeny of a specified person, at any distance of time or through any number of generations.', '後裔、子孫', 'https://api.dictionaryapi.dev/media/pronunciations/en/descendant-us.mp3', 1, '2026-06-01 14:48:14'),
(1739, 'descent', 1, '/dɪˈsɛnt/', 'An instance of descending; act of coming down.', '下降、血統、下坡', 'https://api.dictionaryapi.dev/media/pronunciations/en/descent-us.mp3', 1, '2026-06-01 14:48:14'),
(1740, 'describe', 2, '/dəˈskɹaɪb/', 'To represent in words.', '描述、描寫、形容', 'https://api.dictionaryapi.dev/media/pronunciations/en/describe-us.mp3', 1, '2026-06-01 14:48:14'),
(1741, 'description', 1, '/dɪˈskɹɪpʃən/', 'A sketch or account of anything in words; a portraiture or representation in language; an enumeration of the essential qualities of a thing or species.', '描寫、描述、說明書', 'https://api.dictionaryapi.dev/media/pronunciations/en/description-us.mp3', 1, '2026-06-01 14:48:14'),
(1742, 'desert', 1, '/dɪˈzɜːt/', '(usually in the plural) That which is deserved or merited; a just punishment or reward', '沙漠、荒原', 'https://api.dictionaryapi.dev/media/pronunciations/en/desert-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(1743, 'desert', 2, '/dɪˈzɜːt/', '(usually in the plural) That which is deserved or merited; a just punishment or reward', '遺棄、拋棄、逃跑', 'https://api.dictionaryapi.dev/media/pronunciations/en/desert-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(1744, 'deserve', 2, '/dɪˈzɜːv/', 'To be entitled to, as a result of past actions; to be worthy to have.', '應受、值得', 'https://api.dictionaryapi.dev/media/pronunciations/en/deserve-us.mp3', 1, '2026-06-01 14:48:14'),
(1745, 'design', 1, '/dɪˈzaɪn/', 'A specification of an object or process, referring to requirements to be satisfied and thus conditions to be met for them to solve a problem.', '設計、藍圖、圖案', 'https://api.dictionaryapi.dev/media/pronunciations/en/design-us.mp3', 1, '2026-06-01 14:48:14'),
(1746, 'design', 2, '/dɪˈzaɪn/', 'To plan and carry out (a picture, work of art, construction etc.).', '設計、構思、計劃', 'https://api.dictionaryapi.dev/media/pronunciations/en/design-us.mp3', 1, '2026-06-01 14:48:14'),
