(1913, 'dissident', 3, '', 'In a manner that disagrees; dissenting; discordant.', '持異議的、不同意的', 'https://api.dictionaryapi.dev/media/pronunciations/en/dissident-au.mp3', 1, '2026-06-01 14:48:14'),
(1914, 'dissuade', 2, '/dɪˈsweɪd/', 'To convince not to try or do.', '勸阻', 'https://dictionaryapi.dev/dissuade', 1, '2026-06-01 14:48:14'),
(1915, 'distance', 1, '/ˈdɪs.təns/', 'The amount of space between two points, usually geographical points, usually (but not necessarily) measured along a straight line.', '距離、遠處、疏遠', 'https://api.dictionaryapi.dev/media/pronunciations/en/distance-us.mp3', 1, '2026-06-01 14:48:14'),
(1916, 'distant', 3, '/ˈdɪstənt/', 'Far off (physically, logically or mentally).', '遙遠的、疏遠的、冷淡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/distant-us.mp3', 1, '2026-06-01 14:48:14'),
(1917, 'distinct', 3, '/dɪsˈtɪŋkt/', 'Capable of being perceived very clearly.', '清晰的、明顯的、截然不同的', 'https://api.dictionaryapi.dev/media/pronunciations/en/distinct-us.mp3', 1, '2026-06-01 14:48:14'),
(1918, 'distinction', 1, '/dɪˈstɪŋkʃən/', 'That which distinguishes; a single occurrence of a determining factor or feature, the fact of being divided; separation, discrimination.', '區別、差別、優秀、榮譽', 'https://api.dictionaryapi.dev/media/pronunciations/en/distinction-us.mp3', 1, '2026-06-01 14:48:14'),
(1919, 'distinctively', 2, '', 'In a distinctive manner; in a way that is notable for its difference.', '獨特地、與眾不同地', 'https://dictionaryapi.dev/distinctively', 1, '2026-06-01 14:48:14'),
(1920, 'distinguish', 2, '/dɪsˈtɪŋɡwɪʃ/', 'To recognize someone or something as different from others based on its characteristics.', '區分、辨別、使傑出', 'https://api.dictionaryapi.dev/media/pronunciations/en/distinguish-us.mp3', 1, '2026-06-01 14:48:14'),
(1921, 'distinguished', 3, '/dɪsˈtɪŋɡwɪʃt/', 'Celebrated, well-known or eminent because of past achievements; prestigious', '卓越的、傑出的、高貴的', 'https://api.dictionaryapi.dev/media/pronunciations/en/distinguished-us.mp3', 1, '2026-06-01 14:48:14'),
(1922, 'distort', 3, '/dɪsˈtɔːt/', 'Distorted; misshapen.', '扭曲、歪曲、曲解', 'https://api.dictionaryapi.dev/media/pronunciations/en/distort-uk.mp3', 1, '2026-06-01 14:48:14'),
(1923, 'distract', 2, '/dɪsˈtɹækt/', 'To divert the attention of.', '分散（注意力）、使分心', 'https://dictionaryapi.dev/distract', 1, '2026-06-01 14:48:14'),
(1924, 'distress', 1, '/dɪˈstɹɛs/', '(Cause of) discomfort.', '痛苦、悲痛、危難', 'https://api.dictionaryapi.dev/media/pronunciations/en/distress-us.mp3', 1, '2026-06-01 14:48:14'),
(1925, 'distribute', 2, '/dɨˈstɹɪbjuːt/', 'To divide into portions and dispense.', '分發、分配、分銷', 'https://api.dictionaryapi.dev/media/pronunciations/en/distribute-us.mp3', 1, '2026-06-01 14:48:14'),
(1926, 'distribution', 1, '/ˌdɪstɹəˈbjuːʃən/', 'An act of distributing or state of being distributed.', '分配、分發、分佈', 'https://api.dictionaryapi.dev/media/pronunciations/en/distribution-us.mp3', 1, '2026-06-01 14:48:14'),
(1927, 'district', 1, '/ˈdɪstɹɪkt/', 'An administrative division of an area.', '行政區、區域、地方', 'https://api.dictionaryapi.dev/media/pronunciations/en/district-us.mp3', 1, '2026-06-01 14:48:14'),
(1928, 'distrust', 2, '/dɪsˈtɹʊst/', 'To put no trust in; to have no confidence in.', '不信任、懷疑', 'https://api.dictionaryapi.dev/media/pronunciations/en/distrust-us.mp3', 1, '2026-06-01 14:48:14'),
(1929, 'disturb', 2, '/dɪsˈtɜːb/', 'To confuse a quiet, constant state or a calm, continuous flow, in particular: thoughts, actions or liquids.', '打擾、打亂、使不安', 'https://api.dictionaryapi.dev/media/pronunciations/en/disturb-us.mp3', 1, '2026-06-01 14:48:14'),
(1930, 'disturbing', 3, '/dɪsˈtɜːbɪŋ/', 'Causing distress or worry; upsetting or unsettling.', '令人不安的、打擾的', 'https://dictionaryapi.dev/disturbing', 1, '2026-06-01 14:48:14'),
(1931, 'ditch', 1, '/dɪtʃ/', 'A trench; a long, shallow indentation, as for irrigation or drainage.', '溝渠、壕溝', 'https://api.dictionaryapi.dev/media/pronunciations/en/ditch-us.mp3', 1, '2026-06-01 14:48:14'),
(1932, 'dive', 1, '/ˈdaɪv/', 'A jump or plunge into water.', '潛水、跳水、俯衝、小酒館', 'https://api.dictionaryapi.dev/media/pronunciations/en/dive-1-us.mp3', 1, '2026-06-01 14:48:14'),
(1933, 'dive', 2, '/ˈdaɪv/', 'To swim under water.', '跳水、潛水、俯衝', 'https://api.dictionaryapi.dev/media/pronunciations/en/dive-1-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(1934, 'diverse', 3, '/daɪˈvɜːs/', 'Consisting of many different elements; various.', '多元的、不同的、多樣的', 'https://api.dictionaryapi.dev/media/pronunciations/en/diverse-us.mp3', 1, '2026-06-01 14:48:14'),
(1935, 'diversify', 2, '', 'To make diverse or various in form or quality; to give variety to distinguish by numerous differences or aspects.', '使多樣化、擴大經營範圍', 'https://dictionaryapi.dev/diversify', 1, '2026-06-01 14:48:14'),
(1936, 'diversion', 1, '/daɪˈvɜːʃən/', 'A tactic used to draw attention away from the real threat or action.', '轉移、消遣、改道', 'https://api.dictionaryapi.dev/media/pronunciations/en/diversion-us.mp3', 1, '2026-06-01 14:48:14'),
(1937, 'diversity', 1, '/daɪˈvɜː(ɹ)sɪti/', 'The quality of being diverse or different; difference or unlikeness.', '多樣性、多元化', 'https://api.dictionaryapi.dev/media/pronunciations/en/diversity-uk.mp3', 1, '2026-06-01 14:48:14'),
(1938, 'divide', 1, '/dɪˈvaɪd/', 'A thing that divides.', '分水嶺、分歧', 'https://api.dictionaryapi.dev/media/pronunciations/en/divide-us.mp3', 1, '2026-06-01 14:48:14'),
(1939, 'divide', 2, '/dɪˈvaɪd/', 'To split or separate (something) into two or more parts.', '劃分、分開、除以', 'https://api.dictionaryapi.dev/media/pronunciations/en/divide-us.mp3', 1, '2026-06-01 14:48:14'),
(1940, 'dividend', 1, '/ˈdɪvɪdɛnd/', 'A number or expression that is to be divided by another.', '股利、紅利、被除數', 'https://api.dictionaryapi.dev/media/pronunciations/en/dividend-us.mp3', 1, '2026-06-01 14:48:14'),
(1941, 'divine', 3, '/dɪˈvaɪn/', 'Of or pertaining to a god.', '神聖的、非凡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/divine-us.mp3', 1, '2026-06-01 14:48:14'),
(1942, 'division', 1, '/dɪˈvɪʒən/', 'The act or process of dividing anything.', '部門、劃分、除法', 'https://api.dictionaryapi.dev/media/pronunciations/en/division-us.mp3', 1, '2026-06-01 14:48:14'),
(1943, 'division', 2, '/dɪˈvɪʒən/', 'The act or process of dividing anything.', '部門、劃分、除法', 'https://api.dictionaryapi.dev/media/pronunciations/en/division-us.mp3', 1, '2026-06-01 14:48:14'),
(1944, 'divorce', 1, '/dɪˈvɔːs/', 'The legal dissolution of a marriage.', '離婚、脫離', 'https://dictionaryapi.dev/divorce', 1, '2026-06-01 14:48:14'),
(1945, 'divorce', 2, '/dɪˈvɔːs/', 'To legally dissolve a marriage between two people.', '與...離婚、使分離', 'https://dictionaryapi.dev/divorce', 1, '2026-06-01 14:48:14'),
(1946, 'divorcee', 1, '/dɪvɔːˈsiː/', 'A person divorced.', '離婚者（尤指女性）', 'https://dictionaryapi.dev/divorcee', 1, '2026-06-01 14:48:14'),
(1947, 'dizzy', 3, '/ˈdɪzi/', 'Having a sensation of whirling, with a tendency to fall; giddy; feeling unbalanced or lightheaded.', '頭暈的、眩暈的、使人眼花繚亂的', 'https://api.dictionaryapi.dev/media/pronunciations/en/dizzy-us.mp3', 1, '2026-06-01 14:48:14'),
(1948, 'dock', 1, '/dɒk/', 'Any of the genus Rumex of coarse weedy plants with small green flowers related to buckwheat, especially common dock, and used as potherbs and in folk medicine, especially in curing nettle rash.', '碼頭、被告席', 'https://api.dictionaryapi.dev/media/pronunciations/en/dock-us.mp3', 1, '2026-06-01 14:48:14'),
(1949, 'dock', 2, '/dɒk/', 'Any of the genus Rumex of coarse weedy plants with small green flowers related to buckwheat, especially common dock, and used as potherbs and in folk medicine, especially in curing nettle rash.', '靠碼頭、引入船塢', 'https://api.dictionaryapi.dev/media/pronunciations/en/dock-us.mp3', 1, '2026-06-01 14:48:14'),
(1950, 'doctor', 1, '/ˈdɒktə/', 'A physician; a member of the medical profession; one who is trained and licensed to heal the sick or injured. The final examination and qualification may award a doctor degree in which case the post-nominal letters are D.O., DPM, M.D., DMD, DDS, in the US or MBBS in the UK.', '醫生、博士', 'https://api.dictionaryapi.dev/media/pronunciations/en/doctor-uk.mp3', 1, '2026-06-01 14:48:14'),
(1951, 'document', 1, '/ˈdɒkjʊmənt/', 'An original or official paper used as the basis, proof, or support of anything else, including any writing, book, or other instrument conveying information pertinent to such proof or support.', '文件、公文、文檔', 'https://api.dictionaryapi.dev/media/pronunciations/en/document-uk-verb.mp3', 1, '2026-06-01 14:48:14'),
(1952, 'document', 2, '/ˈdɒkjʊmənt/', 'To record in documents.', '用文件證明、記載', 'https://api.dictionaryapi.dev/media/pronunciations/en/document-uk-verb.mp3', 1, '2026-06-01 14:48:14'),
(1953, 'documentary', 1, '/ˌdɒk.jəˈmɛn.tɹi/', 'A film, TV program, publication etc. which presents a social, political, scientific or historical subject in a factual or informative manner.', '紀錄片', 'https://dictionaryapi.dev/documentary', 1, '2026-06-01 14:48:14'),
(1954, 'dodge', 1, '/dɒdʒ/', 'An act of dodging.', '閃躲、託詞', 'https://api.dictionaryapi.dev/media/pronunciations/en/dodge-us.mp3', 1, '2026-06-01 14:48:14'),
(1955, 'dodge', 2, '/dɒdʒ/', 'To avoid (something) by moving suddenly out of the way.', '閃身躲開、迴避（問題）', 'https://api.dictionaryapi.dev/media/pronunciations/en/dodge-us.mp3', 1, '2026-06-01 14:48:14'),
(1956, 'dog', 1, '/dɑɡ/', 'A mammal, Canis familiaris or Canis lupus familiaris, that has been domesticated for thousands of years, of highly variable appearance due to human breeding.', '狗', 'https://api.dictionaryapi.dev/media/pronunciations/en/dog-uk.mp3', 1, '2026-06-01 14:48:14'),
(1957, 'dogmatic', 3, '/dɒɡˈmatɪk/', 'Adhering only to principles which are true a priori, rather than truths based on evidence or deduction.', '武斷的、教條的', 'https://dictionaryapi.dev/dogmatic', 1, '2026-06-01 14:48:14'),
(1958, 'dole', 1, '/dɔʊl/', 'Money or other goods given as charity.', '失業救濟金', 'https://api.dictionaryapi.dev/media/pronunciations/en/dole-uk.mp3', 1, '2026-06-01 14:48:14'),
(1959, 'dole', 2, '/dɔʊl/', 'To distribute in small amounts; to share out small portions of a meager resource.', '發放（救濟金等）', 'https://api.dictionaryapi.dev/media/pronunciations/en/dole-uk.mp3', 1, '2026-06-01 14:48:14'),
(1960, 'doll', 1, '', 'A toy in the form of a human.', '洋娃娃、玩偶', 'https://api.dictionaryapi.dev/media/pronunciations/en/doll-au.mp3', 1, '2026-06-01 14:48:14'),
(1961, 'dollar', 1, '/dɔlɚ/', 'Official designation for currency in some parts of the world, including Canada, the United States, Australia, New Zealand, Hong Kong, and elsewhere. Its symbol is $.', '元（美金等貨幣單位）', 'https://api.dictionaryapi.dev/media/pronunciations/en/dollar-us.mp3', 1, '2026-06-01 14:48:14'),
(1962, 'dolphin', 1, '/ˈdɒlfɪn/', 'A carnivorous aquatic mammal in one of several families of order Cetacea, famed for its intelligence and occasional willingness to approach humans.', '海豚', 'https://api.dictionaryapi.dev/media/pronunciations/en/dolphin-us.mp3', 1, '2026-06-01 14:48:14'),
(1963, 'domain', 1, '/dəʊˈmeɪn/', 'A geographic area owned or controlled by a single person or organization.', '領域、領土、網域', 'https://api.dictionaryapi.dev/media/pronunciations/en/domain-uk.mp3', 1, '2026-06-01 14:48:14'),
(1964, 'domestic', 3, '/dəˈmɛstɪk/', 'Of or relating to the home.', '國內的、家庭的、馴養的', 'https://api.dictionaryapi.dev/media/pronunciations/en/domestic-us.mp3', 1, '2026-06-01 14:48:14'),
(1965, 'dominant', 3, '/ˈdɒmɪnənt/', 'Ruling; governing; prevailing', '佔優勢的、支配的、主導的', 'https://api.dictionaryapi.dev/media/pronunciations/en/dominant-uk.mp3', 1, '2026-06-01 14:48:14'),
(1966, 'dominate', 2, '/ˈdɒməˌneɪt/', 'To govern, rule or control by superior authority or power', '支配、統治、在...中佔首要地位', 'https://dictionaryapi.dev/dominate', 1, '2026-06-01 14:48:14'),
(1967, 'donate', 2, '/dəʊˈneɪt/', 'To make a donation; to give away something of value to support or contribute towards a cause or for the benefit of another.', '捐贈、捐獻', 'https://api.dictionaryapi.dev/media/pronunciations/en/donate-us.mp3', 1, '2026-06-01 14:48:14'),
(1968, 'donation', 1, '/dəʊˈneɪʃən/', 'A voluntary gift or contribution for a specific cause.', '捐款、捐贈物、捐獻', 'https://api.dictionaryapi.dev/media/pronunciations/en/donation-us.mp3', 1, '2026-06-01 14:48:14'),
(1969, 'done', 3, '', '(of food) Ready, fully cooked.', '（食物）煮熟的、熟透的', 'https://api.dictionaryapi.dev/media/pronunciations/en/done-1-ca.mp3', 1, '2026-06-01 14:48:14'),
(1970, 'donkey', 1, '/ˈdɒŋki/', 'A domestic animal, Equus asinus asinus, similar to a horse', '驢子、傻瓜', 'https://api.dictionaryapi.dev/media/pronunciations/en/donkey-us.mp3', 1, '2026-06-01 14:48:14'),
(1971, 'donor', 1, '/ˈdəʊnə/', 'One who makes a donation.', '捐贈者、贈與人、捐血者', 'https://api.dictionaryapi.dev/media/pronunciations/en/donor-us.mp3', 1, '2026-06-01 14:48:14'),
(1972, 'doom', 1, '/duːm/', 'Destiny, especially terrible.', '厄運、毀滅、死亡', 'https://api.dictionaryapi.dev/media/pronunciations/en/doom-us.mp3', 1, '2026-06-01 14:48:14'),
(1973, 'doom', 2, '/duːm/', 'To pronounce sentence or judgment on; to condemn.', '注定、使毀滅', 'https://api.dictionaryapi.dev/media/pronunciations/en/doom-us.mp3', 1, '2026-06-01 14:48:14'),
(1974, 'door', 1, '/dɔː/', 'A portal of entry into a building, room, or vehicle, consisting of a rigid plane movable on a hinge. Doors are frequently made of wood or metal. May have a handle to help open and close, a latch to hold the door closed and a lock that ensures the door cannot be opened without the key.', '門、出入口', 'https://api.dictionaryapi.dev/media/pronunciations/en/door-uk.mp3', 1, '2026-06-01 14:48:14'),
(1975, 'dormitory', 1, '/ˈdɔɹmɪˌtɔɹi/', 'A room containing a number of beds (and often some other furniture and/or utilities) for sleeping, often applied to student and backpacker accommodation of this kind.', '宿舍', 'https://dictionaryapi.dev/dormitory', 1, '2026-06-01 14:48:14'),
(1976, 'dosage', 1, '', 'The administration of a medication etc, in a measured amount; dosing.', '劑量、用量', 'https://dictionaryapi.dev/dosage', 1, '2026-06-01 14:48:14'),
(1977, 'dose', 1, '', 'N/A', '（藥物一劑的）劑量、一劑', NULL, 1, '2026-06-01 14:48:14'),
(1978, 'dot', 1, '', 'A small, round spot.', '點、小圓點', 'https://api.dictionaryapi.dev/media/pronunciations/en/dot-au.mp3', 1, '2026-06-01 14:48:14'),
(1979, 'dot', 2, '', 'To cover with small spots (of some liquid).', '點綴、散布於', 'https://api.dictionaryapi.dev/media/pronunciations/en/dot-au.mp3', 1, '2026-06-01 14:48:14'),
(1980, 'double', 1, '/ˈdʌb.əl/', 'Twice the number, amount, size, etc.', '兩倍、雙倍', 'https://api.dictionaryapi.dev/media/pronunciations/en/double-us.mp3', 1, '2026-06-01 14:48:14'),
(1981, 'double', 2, '/ˈdʌb.əl/', 'To multiply by two.', '使加倍、摺疊', 'https://api.dictionaryapi.dev/media/pronunciations/en/double-us.mp3', 1, '2026-06-01 14:48:14'),
(1982, 'double', 3, '/ˈdʌb.əl/', 'Made up of two matching or complementary elements.', '雙重的、兩倍的', 'https://api.dictionaryapi.dev/media/pronunciations/en/double-us.mp3', 1, '2026-06-01 14:48:14'),
(1983, 'double', 4, '/ˈdʌb.əl/', 'Twice over; twofold; doubly.', '雙倍地、兩倍地', 'https://api.dictionaryapi.dev/media/pronunciations/en/double-us.mp3', 1, '2026-06-01 14:48:14'),
(1984, 'doubt', 1, '/dʌʊt/', 'Disbelief or uncertainty (about something); a particular instance of such disbelief or uncertainty.', '懷疑、疑慮', 'https://api.dictionaryapi.dev/media/pronunciations/en/doubt-us.mp3', 1, '2026-06-01 14:48:14'),
(1985, 'doubt', 2, '/dʌʊt/', 'To be undecided about; to lack confidence in; to disbelieve, to question.', '懷疑、不信任', 'https://api.dictionaryapi.dev/media/pronunciations/en/doubt-us.mp3', 1, '2026-06-01 14:48:14'),
(1986, 'doubtful', 3, '/ˈdaʊtfəl/', 'Subject to, or causing doubt.', '懷疑的、不確定的、可疑的', 'https://api.dictionaryapi.dev/media/pronunciations/en/doubtful-us.mp3', 1, '2026-06-01 14:48:14'),
(1987, 'doubtless', 4, '/ˈdʌʊ̯tləs/', 'Without doubt; very probably, in all likelihood; doubtlessly.', '無疑地、必定', 'https://api.dictionaryapi.dev/media/pronunciations/en/doubtless-us.mp3', 1, '2026-06-01 14:48:14'),
(1988, 'dough', 1, '/dʌf/', 'A thick, malleable substance made by mixing flour with other ingredients such as water, eggs, and/or butter, that is made into a particular form and then baked.', '麵團', 'https://api.dictionaryapi.dev/media/pronunciations/en/dough-uk.mp3', 1, '2026-06-01 14:48:14'),
(1989, 'doughnut', 1, '/ˈdoʊnət/', 'A deep-fried piece of dough or batter, commonly of a toroidal (a ring doughnut) shape, often mixed with various sweeteners and flavourings; or flattened sphere (a filled doughnut) shape filled with jam, custard or cream.', '甜甜圈', 'https://api.dictionaryapi.dev/media/pronunciations/en/doughnut-us.mp3', 1, '2026-06-01 14:48:14'),
(1990, 'dove', 1, '/dʌv/', 'A pigeon, especially one smaller in size; a bird (often arbitrarily called either a pigeon or a dove or both) of more than 300 species of the family Columbidae.', '鴿子、溫和派人物', 'https://api.dictionaryapi.dev/media/pronunciations/en/dove-1.mp3', 1, '2026-06-01 14:48:14'),
(1991, 'down', 1, '/daʊn/', 'A negative aspect; a downer.', '絨毛、羽絨、不幸', 'https://api.dictionaryapi.dev/media/pronunciations/en/down-us.mp3', 1, '2026-06-01 14:48:14'),
(1992, 'down', 2, '/daʊn/', 'To knock (someone or something) down; to cause to come down, to fell.', '向下、沿著...而下', 'https://api.dictionaryapi.dev/media/pronunciations/en/down-us.mp3', 1, '2026-06-01 14:48:14'),
(1993, 'down', 3, '/daʊn/', 'Sad, unhappy, depressed, feeling low.', '向下的、下行的', 'https://api.dictionaryapi.dev/media/pronunciations/en/down-us.mp3', 1, '2026-06-01 14:48:14'),
(1994, 'down', 4, '/daʊn/', 'From a higher position to a lower one; downwards.', '向下地、在下方', 'https://api.dictionaryapi.dev/media/pronunciations/en/down-us.mp3', 1, '2026-06-01 14:48:14'),
(1995, 'down', 5, '/daʊn/', 'From the higher end to the lower of.', '沿著...向下', 'https://api.dictionaryapi.dev/media/pronunciations/en/down-us.mp3', 1, '2026-06-01 14:48:14'),
(1996, 'downstairs', 1, '/daʊnˈstɛəz/', 'The lower floor of a house, at ground level.', '樓下', 'https://api.dictionaryapi.dev/media/pronunciations/en/downstairs-us.mp3', 1, '2026-06-01 14:48:14'),
(1997, 'downstairs', 3, '/daʊnˈstɛəz/', 'A floor lower than the current one.', '樓下的', 'https://api.dictionaryapi.dev/media/pronunciations/en/downstairs-us.mp3', 1, '2026-06-01 14:48:14'),
(1998, 'downstairs', 4, '/daʊnˈstɛəz/', 'Living, stepping, or coming down the stairs', '往樓下、在樓下', 'https://api.dictionaryapi.dev/media/pronunciations/en/downstairs-us.mp3', 1, '2026-06-01 14:48:14'),
(1999, 'downtown', 1, '', 'The main business part of a city or town, usually located at or near its center.', '市中心、商業區', 'https://dictionaryapi.dev/downtown', 1, '2026-06-01 14:48:14'),
