(2380, 'explore', 2, '/ɪkˈsplɔː/', 'To seek for something or after someone.', '探索、勘探、探查', 'https://api.dictionaryapi.dev/media/pronunciations/en/explore-us.mp3', 1, '2026-06-01 14:48:14'),
(2381, 'explosion', 1, '/ɪkˈspləʊ.ʒən/', 'A violent release of energy (sometimes mechanical, nuclear, or chemical.)', '爆炸、轟響、激增', 'https://api.dictionaryapi.dev/media/pronunciations/en/explosion-us.mp3', 1, '2026-06-01 14:48:14'),
(2382, 'explosive', 1, '', 'Any explosive substance.', '炸藥、爆裂物', 'https://api.dictionaryapi.dev/media/pronunciations/en/explosive-au.mp3', 1, '2026-06-01 14:48:14'),
(2383, 'explosive', 3, '', 'With the capability to, or likely to, explode.', '爆炸（性）的、易爆的、暴躁的', 'https://api.dictionaryapi.dev/media/pronunciations/en/explosive-au.mp3', 1, '2026-06-01 14:48:14'),
(2384, 'export', 1, '/ˈɛks.pɔːt/', 'Something that is exported', '出口、出口商品', 'https://api.dictionaryapi.dev/media/pronunciations/en/export-uk.mp3', 1, '2026-06-01 14:48:14'),
(2385, 'export', 2, '/ˈɛks.pɔːt/', 'To carry away', '出口、輸出', 'https://api.dictionaryapi.dev/media/pronunciations/en/export-uk.mp3', 1, '2026-06-01 14:48:14'),
(2386, 'expose', 2, '/ɪkˈspəʊz/', 'To reveal, uncover, make visible, bring to light, introduce to.', '暴露、揭露、使曝光', 'https://api.dictionaryapi.dev/media/pronunciations/en/expose-us.mp3', 1, '2026-06-01 14:48:14'),
