(2402, 'extreme', 1, '/ɛkˈstɹiːm/', 'The greatest or utmost point, degree or condition.', '極端、末端、極度', 'https://api.dictionaryapi.dev/media/pronunciations/en/extreme-us.mp3', 1, '2026-06-01 14:48:14'),
(2403, 'extreme', 3, '/ɛkˈstɹiːm/', 'Of a place, the most remote, farthest or outermost.', '極端的、極度的、偏激的', 'https://api.dictionaryapi.dev/media/pronunciations/en/extreme-us.mp3', 1, '2026-06-01 14:48:14'),
(2404, 'eye', 1, '/aɪ/', 'An organ through which animals see (perceive surroundings via light).', '眼睛、目光、見解', 'https://api.dictionaryapi.dev/media/pronunciations/en/eye-us.mp3', 1, '2026-06-01 14:48:14'),
(2405, 'eye', 2, '/aɪ/', 'To observe carefully or appraisingly.', '看、注視、觀察', 'https://api.dictionaryapi.dev/media/pronunciations/en/eye-us.mp3', 1, '2026-06-01 14:48:14'),
