(2415, 'factory', 1, '/ˈfæktəɹi/', 'A trading establishment, especially set up by merchants working in a foreign country.', '工廠、製造廠', 'https://api.dictionaryapi.dev/media/pronunciations/en/factory-uk.mp3', 1, '2026-06-01 14:48:14'),
(2416, 'faculty', 1, '/ˈfæ.kəl.ti/', 'The academic staff at schools, colleges, universities or not-for-profit research institutes, as opposed to the students or support staff.', '官能、機能、全體教職員、才能', 'https://api.dictionaryapi.dev/media/pronunciations/en/faculty-us.mp3', 1, '2026-06-01 14:48:14'),
(2417, 'fade', 2, '/feɪd/', 'To grow weak; to lose strength; to decay; to perish gradually; to wither, as a plant.', '褪色、凋謝、逐漸消失', 'https://api.dictionaryapi.dev/media/pronunciations/en/fade-au.mp3', 1, '2026-06-01 14:48:14'),
(2418, 'fail', 1, '/feɪl/', 'Poor quality; substandard workmanship.', '不及格者、失敗者', 'https://api.dictionaryapi.dev/media/pronunciations/en/fail-us.mp3', 1, '2026-06-01 14:48:14'),
(2419, 'fail', 2, '/feɪl/', 'To be unsuccessful.', '失敗、未能做到、不及格、衰退', 'https://api.dictionaryapi.dev/media/pronunciations/en/fail-us.mp3', 1, '2026-06-01 14:48:14'),
(2420, 'failure', 1, '/ˈfeɪl.jɚ/', 'State or condition of not meeting a desirable or intended objective, opposite of success.', '失敗、故障、不及格、不履行', 'https://api.dictionaryapi.dev/media/pronunciations/en/failure-ca.mp3', 1, '2026-06-01 14:48:14'),
(2421, 'faint', 1, '/feɪnt/', 'The act of fainting, syncope.', '昏厥、昏倒', 'https://api.dictionaryapi.dev/media/pronunciations/en/faint-us.mp3', 1, '2026-06-01 14:48:14');
