(2431, 'fake', 1, '/feɪk/', 'Something which is not genuine, or is presented fraudulently.', '複製品、贗品、騙子', 'https://api.dictionaryapi.dev/media/pronunciations/en/fake-us.mp3', 1, '2026-06-01 14:48:14'),
(2432, 'fake', 2, '/feɪk/', 'To cheat; to swindle; to steal; to rob.', '偽造、捏造、假裝', 'https://api.dictionaryapi.dev/media/pronunciations/en/fake-us.mp3', 1, '2026-06-01 14:48:14'),
(2433, 'fake', 3, '/feɪk/', 'Not real; false, fraudulent.', '假的、偽造的、冒充的', 'https://api.dictionaryapi.dev/media/pronunciations/en/fake-us.mp3', 1, '2026-06-01 14:48:14'),
