(2865, 'guard', 1, '', 'A person who, or thing that, protects or watches over something.', '衛兵、看守、防護裝置', 'https://api.dictionaryapi.dev/media/pronunciations/en/guard-au.mp3', 1, '2026-06-01 14:48:14'),
(2866, 'guard', 2, '', 'To protect from danger; to secure against surprise, attack, or injury; to keep in safety; to defend.', '保衛、守衛、看守、防範', 'https://api.dictionaryapi.dev/media/pronunciations/en/guard-au.mp3', 1, '2026-06-01 14:48:14'),
(2867, 'guardian', 1, '/ˈɡɑːdɪən/', 'Someone who guards, watches over, or protects.', '監護人、保護者', 'https://api.dictionaryapi.dev/media/pronunciations/en/guardian-us.mp3', 1, '2026-06-01 14:48:14'),
(2868, 'guess', 1, '/ɡɛs/', 'To reach a partly (or totally) unqualified conclusion.', '猜測、推測', 'https://api.dictionaryapi.dev/media/pronunciations/en/guess-us.mp3', 1, '2026-06-01 14:48:14'),
(2869, 'guess', 2, '/ɡɛs/', 'To reach a partly (or totally) unqualified conclusion.', '猜測、推測、猜中', 'https://api.dictionaryapi.dev/media/pronunciations/en/guess-us.mp3', 1, '2026-06-01 14:48:14'),
(2870, 'guest', 1, '/ɡɛst/', 'A recipient of hospitality, specifically someone staying by invitation at the house of another.', '客人、賓客、顧客、來賓', 'https://api.dictionaryapi.dev/media/pronunciations/en/guest-us.mp3', 1, '2026-06-01 14:48:14'),
(2871, 'guidance', 1, '/ˈɡaɪdəns/', 'The act or process of guiding.', '指導、引導、諮詢', 'https://dictionaryapi.dev/guidance', 1, '2026-06-01 14:48:14'),
(2872, 'guideline', 1, '', 'A non-specific rule or principle that provides direction to action or behaviour.', '指導方針、準則', 'https://dictionaryapi.dev/guideline', 1, '2026-06-01 14:48:14'),
(2873, 'guilt', 1, '/ɡɪlt/', 'Responsibility for wrongdoing.', '內疚、罪行、內疚感', 'https://dictionaryapi.dev/guilt', 1, '2026-06-01 14:48:14'),
(2874, 'guilty', 3, '/ˈɡɪl.ti/', 'Responsible for a dishonest act.', '有罪的、內疚的', 'https://api.dictionaryapi.dev/media/pronunciations/en/guilty-us.mp3', 1, '2026-06-01 14:48:14'),
(2875, 'guitar', 1, '/ɡɪˈtɑː(ɹ)/', 'A stringed musical instrument, of European origin, usually with a fretted fingerboard and six strings, played with the fingers or a plectrum (guitar pick).', '吉他', 'https://api.dictionaryapi.dev/media/pronunciations/en/guitar-uk.mp3', 1, '2026-06-01 14:48:14'),
(2876, 'gulf', 1, '/ɡʌlf/', 'A hollow place in the earth; an abyss; a deep chasm or basin.', '海灣、深淵、隔閡', 'https://api.dictionaryapi.dev/media/pronunciations/en/gulf-us.mp3', 1, '2026-06-01 14:48:14'),
(2877, 'gum', 1, '/ɡʌm/', '(often in the plural) The flesh around the teeth.', '口香糖、樹膠、牙齦', 'https://api.dictionaryapi.dev/media/pronunciations/en/gum-us.mp3', 1, '2026-06-01 14:48:14'),
(2878, 'gun', 1, '/ɡʌn/', 'A device for projecting a hard object very forcefully; a firearm or cannon.', '槍械、火砲', 'https://api.dictionaryapi.dev/media/pronunciations/en/gun-1-us.mp3', 1, '2026-06-01 14:48:14'),
(2879, 'guy', 1, '/ɡaɪ/', 'An effigy of a man burned on a bonfire on the anniversary of the Gunpowder Plot (5th November).', '傢伙、人、小伙子', 'https://api.dictionaryapi.dev/media/pronunciations/en/guy-us.mp3', 1, '2026-06-01 14:48:14'),
(2880, 'gymnasium', 1, '/dʒɪmˈneɪ.zi.əm/', 'A large room or building for indoor sports.', '體育館、健身房', 'https://api.dictionaryapi.dev/media/pronunciations/en/gymnasium-us.mp3', 1, '2026-06-01 14:48:14'),
(2881, 'gypsy', 1, '/ˈd͡ʒɪp.si/', '(sometimes offensive) A member of the Romani people, or one of the sub-groups (Roma, Sinti, Romanichal, etc).', '吉普賽人', 'https://api.dictionaryapi.dev/media/pronunciations/en/gypsy-us.mp3', 1, '2026-06-01 14:48:14'),
