(2889, 'hairstyle', 1, '', 'The style in which someone\'s hair has been cut and arranged.', '髮型', 'https://dictionaryapi.dev/hairstyle', 1, '2026-06-01 14:48:14'),
(2890, 'half', 1, '/hɑːf/', 'One of two usually roughly equal parts into which anything may be divided, or considered as divided.', '一半、半個', 'https://dictionaryapi.dev/half', 1, '2026-06-01 14:48:14'),
(2891, 'half', 3, '/hɑːf/', 'Consisting of a half (1/2, 50%).', '一半的、半個的', 'https://dictionaryapi.dev/half', 1, '2026-06-01 14:48:14'),
