(2900, 'ham', 1, '/ˈhæːm/', 'The region back of the knee joint; the popliteal space; the hock.', '火腿', 'https://api.dictionaryapi.dev/media/pronunciations/en/ham-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(2901, 'hamburger', 1, '/ˈhæm.bə.ɡə/', 'A hot sandwich consisting of a patty of cooked ground beef or a meat substitute, in a sliced bun, sometimes also containing salad vegetables, condiments, or both.', '漢堡、漢堡肉餅', 'https://dictionaryapi.dev/hamburger', 1, '2026-06-01 14:48:14'),
(2902, 'hand', 1, '/hænd/', 'The part of the forelimb below the forearm or wrist in a human, and the corresponding part in many other animals.', '手、指針、協助、人手', 'https://api.dictionaryapi.dev/media/pronunciations/en/hand-uk.mp3', 1, '2026-06-01 14:48:14'),
(2903, 'hand', 2, '/hænd/', 'To give, pass, or transmit with the hand, literally or figuratively.', '遞交、交給、傳遞', 'https://api.dictionaryapi.dev/media/pronunciations/en/hand-uk.mp3', 1, '2026-06-01 14:48:14'),
(2904, 'handbook', 1, '', 'A topically organized book of reference on a certain field of knowledge, regardless of size.', '手冊、指南', 'https://dictionaryapi.dev/handbook', 1, '2026-06-01 14:48:14'),
(2905, 'handful', 1, '/ˈhæn(d)fəl/', 'The amount that a hand will grasp or contain.', '一把、少數、難管教的人', 'https://api.dictionaryapi.dev/media/pronunciations/en/handful-us.mp3', 1, '2026-06-01 14:48:14'),
(2906, 'handicap', 1, '/ˈhændɪkæp/', 'Something that prevents, hampers, or hinders.', '障礙、不利條件、缺陷', 'https://dictionaryapi.dev/handicap', 1, '2026-06-01 14:48:14'),
(2907, 'handkerchief', 1, '/ˈhæŋkətʃiːf/', 'A piece of cloth, usually square and often fine and elegant, carried for wiping the face, eyes, nose or hands.', '手帕', 'https://api.dictionaryapi.dev/media/pronunciations/en/handkerchief-uk.mp3', 1, '2026-06-01 14:48:14'),
(2908, 'handle', 1, '', 'The part of an object which is (designed to be) held in the hand when used or moved.', '把手、柄', 'https://api.dictionaryapi.dev/media/pronunciations/en/handle-au.mp3', 1, '2026-06-01 14:48:14'),
