(2931, 'harmony', 1, '/ˈhɑːməni/', 'Agreement or accord.', '和諧、融洽、協調', 'https://api.dictionaryapi.dev/media/pronunciations/en/harmony-us.mp3', 1, '2026-06-01 14:48:14'),
(2932, 'harness', 1, '/ˈhɑː(ɹ).nəs/', 'A restraint or support, especially one consisting of a loop or network of rope or straps.', '馬具、挽具、安全帶', 'https://api.dictionaryapi.dev/media/pronunciations/en/harness-us.mp3', 1, '2026-06-01 14:48:14'),
(2933, 'harsh', 3, '', 'Unpleasantly rough to the touch or other senses.', '嚴厲的、粗糙的、刺耳的', 'https://api.dictionaryapi.dev/media/pronunciations/en/harsh-au.mp3', 1, '2026-06-01 14:48:14'),
