(2948, 'head', 1, '/hɛd/', 'The part of the body of an animal or human which contains the brain, mouth and main sense organs.', '頭、頭腦、首長、前端', 'https://api.dictionaryapi.dev/media/pronunciations/en/head-uk.mp3', 1, '2026-06-01 14:48:14'),
(2949, 'head-on', 3, '', 'Direct, abrupt, blunt or unequivocal; not prevaricating.', '迎頭的、正面的', 'https://api.dictionaryapi.dev/media/pronunciations/en/head-on-au.mp3', 1, '2026-06-01 14:48:14'),
(2950, 'head-on', 4, '', 'A collision from the front.', '迎頭地、正面地', 'https://api.dictionaryapi.dev/media/pronunciations/en/head-on-au.mp3', 1, '2026-06-01 14:48:14'),
(2951, 'headache', 1, '/ˈhɛdeɪk/', 'A pain or ache in the head.', '頭痛、令人頭痛的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/headache-us.mp3', 1, '2026-06-01 14:48:14'),
