(3377, 'introduce', 2, '/ˌɪntɹəˈdjuːs/', '(of people) To cause (someone) to be acquainted (with someone else).', '介紹、引進、採用、推行', 'https://api.dictionaryapi.dev/media/pronunciations/en/introduce-us.mp3', 1, '2026-06-01 14:48:14'),
(3378, 'introduction', 1, '/ˌɪntɹəˈdʌkʃən/', 'The act or process of introducing.', '介紹、引進、導言、序幕', 'https://api.dictionaryapi.dev/media/pronunciations/en/introduction-us.mp3', 1, '2026-06-01 14:48:14'),
(3379, 'intuition', 1, '/ˌɪntjʊˈɪʃən/', 'Immediate cognition without the use of conscious rational processes.', '直覺、憑直覺發覺的事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/intuition-us.mp3', 1, '2026-06-01 14:48:14'),
(3380, 'invade', 2, '/ɪnˈveɪd/', 'To move into.', '侵略、侵入、侵犯', 'https://api.dictionaryapi.dev/media/pronunciations/en/invade-us.mp3', 1, '2026-06-01 14:48:14'),
(3381, 'invasion', 1, '/ɪnˈveɪʒən/', 'A military action consisting of armed forces of one geopolitical entity entering territory controlled by another such entity, generally with the objective of conquering territory or altering the established government.', '入侵、侵略、侵犯', 'https://dictionaryapi.dev/invasion', 1, '2026-06-01 14:48:14'),
(3382, 'invent', 2, '/ɪnˈvɛnt/', 'To design a new process or mechanism.', '發明、虛構、捏造', 'https://api.dictionaryapi.dev/media/pronunciations/en/invent-us.mp3', 1, '2026-06-01 14:48:14'),
(3383, 'invention', 1, '/ɪnˈvɛnʃən/', 'Something invented.', '發明、創造、發明物、捏造', 'https://api.dictionaryapi.dev/media/pronunciations/en/invention-us.mp3', 1, '2026-06-01 14:48:14'),
(3384, 'inventor', 1, '/ɪnˈvɛntə/', 'One who invents, either as a hobby or as an occupation.', '發明家', 'https://dictionaryapi.dev/inventor', 1, '2026-06-01 14:48:14'),
(3385, 'invest', 1, '/ɪnˈvɛst/', 'To spend money, time, or energy on something, especially for some benefit or purpose; used with in.', '投資、投入（時間或精力）（此處代碼 1 應指投資行爲之意）', 'https://api.dictionaryapi.dev/media/pronunciations/en/invest-uk.mp3', 1, '2026-06-01 14:48:14'),
(3386, 'invest', 2, '/ɪnˈvɛst/', 'To spend money, time, or energy on something, especially for some benefit or purpose; used with in.', '投資、投入、授予', 'https://api.dictionaryapi.dev/media/pronunciations/en/invest-uk.mp3', 1, '2026-06-01 14:48:14'),
(3387, 'investigate', 2, '[ɪn.ˈves.tɪ.ɡeɪ̯t]', 'To inquire into or study in order to ascertain facts or information.', '調查、研究', 'https://api.dictionaryapi.dev/media/pronunciations/en/investigate-us.mp3', 1, '2026-06-01 14:48:14'),
(3388, 'investigation', 1, '/ɪnˌvɛstəˈɡeɪʃən/', 'The act of investigating; the process of inquiring into or following up; research, especially patient or thorough inquiry or examination', '調查、研究', 'https://api.dictionaryapi.dev/media/pronunciations/en/investigation-us.mp3', 1, '2026-06-01 14:48:14'),
(3389, 'investigator', 1, '', 'One who investigates.', '調查員、偵查員', 'https://dictionaryapi.dev/investigator', 1, '2026-06-01 14:48:14'),
(3390, 'investor', 1, '/ɪnˈvɛstɚ/', 'A person who invests money in order to make a profit.', '投資者', '', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(3391, 'invisible', 3, '/ɪnˈvɪzəb(ə)l/', 'Unable to be seen; out of sight; not visible.', '看不見的、隱形的', 'https://api.dictionaryapi.dev/media/pronunciations/en/invisible-us.mp3', 1, '2026-06-01 14:48:14'),
(3392, 'invitation', 1, '/ɪn.vɪˈteɪ.ʃn̩/', 'The act of inviting; solicitation; the requesting of a person\'s company.', '邀請、邀請函、請帖', 'https://api.dictionaryapi.dev/media/pronunciations/en/invitation-us.mp3', 1, '2026-06-01 14:48:14'),
(3393, 'invite', 2, '/ɪnˈvaɪt/', 'To ask for the presence or participation of someone or something.', '邀請、招致、吸引', 'https://api.dictionaryapi.dev/media/pronunciations/en/invite-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(3394, 'inviting', 3, '/ɪnˈvaɪtɪŋ/', 'Alluring; tempting; attractive.', '吸引人的、誘人的、款待周到的', 'https://dictionaryapi.dev/inviting', 1, '2026-06-01 14:48:14'),
(3395, 'invoke', 2, '/ɪnˈvoʊk/', 'To call upon (a person, a god) for help, assistance or guidance.', '援引、祈求、訴諸（法律）', 'https://dictionaryapi.dev/invoke', 1, '2026-06-01 14:48:14'),
(3396, 'involve', 1, '/ɪnˈvɒlv/', 'To roll or fold up; to wind round; to entwine.', '涉及、包含、使參與（此處代碼 1 應指關聯之意）', 'https://api.dictionaryapi.dev/media/pronunciations/en/involve-uk.mp3', 1, '2026-06-01 14:48:14'),
(3397, 'involve', 2, '/ɪnˈvɒlv/', 'To roll or fold up; to wind round; to entwine.', '包含、需要、使捲入、牽涉', 'https://api.dictionaryapi.dev/media/pronunciations/en/involve-uk.mp3', 1, '2026-06-01 14:48:14'),
(3398, 'inward', 3, '/ˈɪnwəd/', 'Situated on the inside; that is within, inner; belonging to the inside.', '向內的、內心的、裡面的', 'https://api.dictionaryapi.dev/media/pronunciations/en/inward-us.mp3', 1, '2026-06-01 14:48:14'),
(3399, 'iron', 1, '/ˈaɪən/', 'A common, inexpensive metal, silvery grey when untarnished, that rusts, is attracted by magnets, and is used in making steel.', '鐵、熨斗', 'https://api.dictionaryapi.dev/media/pronunciations/en/iron-us.mp3', 1, '2026-06-01 14:48:14'),
(3400, 'iron', 3, '/ˈaɪən/', 'Made of the metal iron.', '鐵製的、堅強的', 'https://api.dictionaryapi.dev/media/pronunciations/en/iron-us.mp3', 1, '2026-06-01 14:48:14'),
(3401, 'ironic', 3, '/aɪˈɹɒn.ɪk/', 'Characterized by or constituting (any kind of) irony.', '諷刺的、挖苦的、出人意料的', 'https://api.dictionaryapi.dev/media/pronunciations/en/ironic-uk.mp3', 1, '2026-06-01 14:48:14'),
(3402, 'irony', 1, '', 'A statement that, when taken in context, may actually mean something different from, or the opposite of, what is written literally; the use of words expressing something other than their literal intention, often in a humorous context.', '諷刺、反諷、具有 community 諷刺意味的事', 'https://api.dictionaryapi.dev/media/pronunciations/en/irony-1-au.mp3', 1, '2026-06-01 14:48:14'),
(3403, 'irregular', 3, '/ɪˈɹɛɡjəlɚ/', 'Nonstandard; not conforming to rules or expectations', '不規則的、不整齊的、不合常規的', 'https://dictionaryapi.dev/irregular', 1, '2026-06-01 14:48:14'),
(3404, 'irrelevant', 3, '', 'Not related, not applicable, unimportant, not connected.', '不相關的、無關係的', 'https://dictionaryapi.dev/irrelevant', 1, '2026-06-01 14:48:14'),
(3405, 'irresponsible', 3, '/ɪrəˈspɑnsɪbəl/', 'Not responsible; exempt from legal responsibility, not to be held accountable.', '不負責任的', 'https://dictionaryapi.dev/irresponsible', 1, '2026-06-01 14:48:14'),
(3406, 'irritable', 3, '/ˈɪɹɪtəbl/', 'Capable of being irritated.', '易怒的、急躁的、過敏的', 'https://dictionaryapi.dev/irritable', 1, '2026-06-01 14:48:14'),
(3407, 'irritate', 2, '/ˈɪɹɪteɪt/', 'To provoke impatience, anger, or displeasure in.', '使憤怒、使過敏、激怒', 'https://api.dictionaryapi.dev/media/pronunciations/en/irritate-us.mp3', 1, '2026-06-01 14:48:14'),
(3408, 'island', 1, '/ˈaɪ̯lənd/', 'A contiguous area of land, smaller than a continent, totally surrounded by water.', '島嶼', 'https://api.dictionaryapi.dev/media/pronunciations/en/island-uk.mp3', 1, '2026-06-01 14:48:14'),
(3409, 'isolate', 2, '', 'To set apart or cut off from others.', '使隔離、使孤立、分離', 'https://api.dictionaryapi.dev/media/pronunciations/en/isolate-us.mp3', 1, '2026-06-01 14:48:14'),
(3410, 'isolated', 3, '/ˈaɪsəleɪtɪd/', 'Placed or standing apart or alone; in isolation.', '孤立的、隔離的、偏遠的', 'https://api.dictionaryapi.dev/media/pronunciations/en/isolated-us.mp3', 1, '2026-06-01 14:48:14'),
(3411, 'isolation', 1, '/ˌaɪsəˈleɪʃən/', 'The state of being isolated, detached, or separated.', '隔離、孤立、孤獨', 'https://dictionaryapi.dev/isolation', 1, '2026-06-01 14:48:14'),
(3412, 'Italian', 1, '', 'N/A', '義大利人、義大利語', NULL, 1, '2026-06-01 14:48:14'),
(3413, 'itch', 2, '/ɪt͡ʃ/', 'A sensation felt on an area of the skin that causes a person or animal to want to scratch.', '發癢、渴望', 'https://api.dictionaryapi.dev/media/pronunciations/en/itch-us.mp3', 1, '2026-06-01 14:48:14'),
(3414, 'item', 1, '[ˈaɪ̯ɾm̩]', 'A distinct physical object.', '項目、條款、一件物品', 'https://api.dictionaryapi.dev/media/pronunciations/en/item-us.mp3', 1, '2026-06-01 14:48:14'),
(3415, 'ivory', 1, '/ˈaɪvəɹi/', 'The hard white form of dentin which forms the tusks of elephants, walruses and other animals.', '象牙、象牙質、乳白色', 'https://api.dictionaryapi.dev/media/pronunciations/en/ivory-us.mp3', 1, '2026-06-01 14:48:14'),
