(3417, 'jacket', 1, '/ˈd͡ʒæk.ɪt/', 'A piece of clothing worn on the upper body outside a shirt or blouse, often waist length to thigh length.', '夾克、外套、書套', 'https://api.dictionaryapi.dev/media/pronunciations/en/jacket-us.mp3', 1, '2026-06-01 14:48:14'),
(3418, 'jail', 1, '/dʒeɪl/', 'A place or institution for the confinement of persons held in lawful custody or detention, especially for minor offenses or with reference to some future judicial proceeding.', '監獄、看守所', 'https://api.dictionaryapi.dev/media/pronunciations/en/jail-us.mp3', 1, '2026-06-01 14:48:14'),
