(4326, 'overtake', 2, '/ˈəʊvə(ɹ).teɪk/', 'To pass a more slowly moving object or entity.', '追上、趕上、超過、突然降臨', 'https://api.dictionaryapi.dev/media/pronunciations/en/overtake-us.mp3', 1, '2026-06-01 14:48:14'),
(4327, 'overthrow', 2, '', 'To bring about the downfall of (a government, etc.), especially by force.', '推翻、打倒、廢除', 'https://api.dictionaryapi.dev/media/pronunciations/en/overthrow-au.mp3', 1, '2026-06-01 14:48:14'),
(4328, 'overturn', 2, '', 'To turn over, capsize or upset.', '翻轉、傾覆、推翻', 'https://dictionaryapi.dev/overturn', 1, '2026-06-01 14:48:14'),
(4329, 'overwhelm', 2, '/ˌovɚˈʍɛlm/', 'To engulf, surge over and submerge.', '壓倒、使不知所措、淹沒', 'https://dictionaryapi.dev/overwhelm', 1, '2026-06-01 14:48:14'),
(4330, 'overwork', 2, '/ˌəʊvəˈwɜːk/', 'To make (someone) work too hard.', '工作過度、使操勞過度', 'https://api.dictionaryapi.dev/media/pronunciations/en/overwork-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4331, 'owe', 2, '/əʊ/', 'To be under an obligation to give something back to someone or to perform some action for someone.', '欠（債、人情等）、把...歸功於', 'https://api.dictionaryapi.dev/media/pronunciations/en/owe-us.mp3', 1, '2026-06-01 14:48:14'),
(4332, 'owl', 1, '/aʊl/', 'Any of various birds of prey of the order Strigiformes that are primarily nocturnal and have forward-looking, binocular vision, limited eye movement, and good hearing.', '貓頭鷹', 'https://api.dictionaryapi.dev/media/pronunciations/en/owl-us.mp3', 1, '2026-06-01 14:48:14'),
(4333, 'own', 2, '/ˈəʊn/', 'Belonging to; possessed; proper to. Often marks a possessive determiner as reflexive, referring back to the subject of the clause or sentence.', '擁有、承認', 'https://api.dictionaryapi.dev/media/pronunciations/en/own-us.mp3', 1, '2026-06-01 14:48:14'),
(4334, 'own', 3, '/ˈəʊn/', 'Belonging to; possessed; proper to. Often marks a possessive determiner as reflexive, referring back to the subject of the clause or sentence.', '自己的', 'https://api.dictionaryapi.dev/media/pronunciations/en/own-us.mp3', 1, '2026-06-01 14:48:14'),
(4335, 'owner', 1, '/ˈəʊnə/', 'One who owns something.', '物主、所有人、主人', 'https://api.dictionaryapi.dev/media/pronunciations/en/owner-us.mp3', 1, '2026-06-01 14:48:14'),
(4336, 'ownership', 1, '', 'The state of having complete legal control of something; possession; proprietorship.', '所有權、產權', 'https://api.dictionaryapi.dev/media/pronunciations/en/ownership-us.mp3', 1, '2026-06-01 14:48:14'),
(4337, 'ox', 1, '', 'An adult castrated male of cattle (B. taurus).', '公牛（通常指閹牛）', 'https://api.dictionaryapi.dev/media/pronunciations/en/ox-ca.mp3', 1, '2026-06-01 14:48:14'),
(4338, 'oxidation', 1, '', 'The combination of a substance with oxygen.', '氧化、氧化作用', 'https://dictionaryapi.dev/oxidation', 1, '2026-06-01 14:48:14'),
(4339, 'oxygen', 1, '/ˈɒksɪdʒən/', 'The chemical element (symbol O) with an atomic number of 8 and relative atomic mass of 15.9994. It is a colorless and odorless gas.', '氧、氧氣', 'https://api.dictionaryapi.dev/media/pronunciations/en/oxygen-us.mp3', 1, '2026-06-01 14:48:14'),
(4340, 'oyster', 1, '/ˈɔɪ.stə(ɹ)/', 'Any of certain marine bivalve mollusks, especially those of the family Ostreidae (the true oysters), usually found adhering to rocks or other fixed objects in shallow water along the seacoasts, or in brackish water in the mouth of rivers.', '牡蠣、生蠔', 'https://api.dictionaryapi.dev/media/pronunciations/en/oyster-us.mp3', 1, '2026-06-01 14:48:14'),
(4341, 'pace', 1, '', 'Step.', '步調、速度、步伐', 'https://api.dictionaryapi.dev/media/pronunciations/en/pace-1-au.mp3', 1, '2026-06-01 14:48:14'),
(4342, 'pace', 2, '', 'To walk back and forth in a small distance.', '踱步、調整步調', 'https://api.dictionaryapi.dev/media/pronunciations/en/pace-1-au.mp3', 1, '2026-06-01 14:48:14'),
(4343, 'pack', 1, '/pæk/', 'A bundle made up and prepared to be carried; especially, a bundle to be carried on the back, but also a load for an animal, a bale.', '包裹、一群、一副（卡牌）', 'https://api.dictionaryapi.dev/media/pronunciations/en/pack-au.mp3', 1, '2026-06-01 14:48:14'),
(4344, 'pack', 2, '/pæk/', 'A bundle made up and prepared to be carried; especially, a bundle to be carried on the back, but also a load for an animal, a bale.', '打包、捆紮、擠滿', 'https://api.dictionaryapi.dev/media/pronunciations/en/pack-au.mp3', 1, '2026-06-01 14:48:14'),
(4345, 'package', 1, '/ˈpækɪdʒ/', 'Something which is packed, a parcel, a box, an envelope.', '包裹、包裝、一整套計劃', 'https://dictionaryapi.dev/package', 1, '2026-06-01 14:48:14'),
(4346, 'package', 2, '/ˈpækɪdʒ/', 'To pack or bundle something.', '包裝、把...打包', 'https://dictionaryapi.dev/package', 1, '2026-06-01 14:48:14'),
(4347, 'pact', 1, '/pækt/', 'An agreement; a compact; a covenant.', '協定、條約、契約', 'https://dictionaryapi.dev/pact', 1, '2026-06-01 14:48:14'),
(4348, 'page', 1, '/peɪd͡ʒ/', 'One of the many pieces of paper bound together within a book or similar document.', '網頁、頁、頁面', 'https://api.dictionaryapi.dev/media/pronunciations/en/page-us.mp3', 1, '2026-06-01 14:48:14'),
(4349, 'pain', 1, '/peɪn/', 'An ache or bodily suffering, or an instance of this; an unpleasant sensation, resulting from a derangement of functions, disease, or injury by violence; hurt.', '疼痛、痛苦、苦惱', 'https://api.dictionaryapi.dev/media/pronunciations/en/pain-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4350, 'painful', 3, '/ˈpeɪn.fəl/', 'Causing pain or distress, either physical or mental.', '痛苦的、令人不快的、困難的', 'https://api.dictionaryapi.dev/media/pronunciations/en/painful-us.mp3', 1, '2026-06-01 14:48:14'),
(4351, 'painfully', 2, '/ˈpeɪnfəli/', 'In a painful manner; as if in pain.', '痛苦地、費力地（原檔標記 2，實為副詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/painfully-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(4352, 'paint', 1, '/peɪnt/', 'A substance that is applied as a liquid or paste, and dries into a solid coating that protects or adds color/colour to an object or surface to which it has been applied.', '油漆、塗料、顏料', 'https://api.dictionaryapi.dev/media/pronunciations/en/paint-us.mp3', 1, '2026-06-01 14:48:14'),
(4353, 'paint', 2, '/peɪnt/', 'To apply paint to.', '繪畫、塗油漆、刷牆', 'https://api.dictionaryapi.dev/media/pronunciations/en/paint-us.mp3', 1, '2026-06-01 14:48:14'),
(4354, 'painter', 1, '/ˈpeɪntə/', 'An artist who paints pictures.', '畫家、油漆工', 'https://api.dictionaryapi.dev/media/pronunciations/en/painter-us.mp3', 1, '2026-06-01 14:48:14'),
(4355, 'painting', 1, '/ˈpeɪn.tɪŋ/', 'An illustration or artwork done with the use of paint.', '畫作、繪畫、油漆業', 'https://api.dictionaryapi.dev/media/pronunciations/en/painting-uk.mp3', 1, '2026-06-01 14:48:14'),
(4356, 'pair', 1, '', 'Two similar or identical things taken together; often followed by of.', '一雙、一對、一副', 'https://api.dictionaryapi.dev/media/pronunciations/en/pair-au.mp3', 1, '2026-06-01 14:48:14'),
(4357, 'pajamas', 1, '/pəˈd͡ʒæ.məz/', 'Clothes for wearing to bed and sleeping in, usually consisting of a loose-fitting shirt and pants/trousers.', '睡衣', 'https://api.dictionaryapi.dev/media/pronunciations/en/pajamas-us.mp3', 1, '2026-06-01 14:48:14'),
(4358, 'pal', 1, '/pal/', 'A friend, buddy, mate, cobber; someone to hang around with.', '夥伴、好友、老哥們', 'https://api.dictionaryapi.dev/media/pronunciations/en/pal-uk.mp3', 1, '2026-06-01 14:48:14'),
(4359, 'palace', 1, '/ˈpæləs/', 'Official residence of a head of state or other dignitary, especially in a monarchical or imperial governmental system.', '宮殿、皇宮、豪華住宅', 'https://api.dictionaryapi.dev/media/pronunciations/en/palace-us.mp3', 1, '2026-06-01 14:48:14'),
(4360, 'pale', 3, '/peɪl/', 'Light in color.', '蒼白的、暗淡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/pale-us.mp3', 1, '2026-06-01 14:48:14'),
(4361, 'palm', 1, '/ˈpæm/', 'Any of various evergreen trees from the family Palmae or Arecaceae, which are mainly found in the tropics.', '手掌、棕櫚樹', 'https://api.dictionaryapi.dev/media/pronunciations/en/palm-us.mp3', 1, '2026-06-01 14:48:14'),
(4362, 'pan', 1, '/pæn/', 'A wide, flat receptacle used around the house, especially for cooking.', '平底鍋、鍋子', 'https://api.dictionaryapi.dev/media/pronunciations/en/pan-us.mp3', 1, '2026-06-01 14:48:14'),
(4363, 'panacea', 1, '/ˌpæn.əˈsiː.ə/', 'A remedy believed to cure all disease and prolong life that was originally sought by alchemists; a cure-all.', '萬靈藥、萬應膏', 'https://api.dictionaryapi.dev/media/pronunciations/en/panacea-us.mp3', 1, '2026-06-01 14:48:14'),
(4364, 'pancake', 1, '/ˈpæn.keɪk/', 'A thin batter cake fried in a pan or on a griddle in oil or butter.', '薄煎餅、鬆餅', 'https://api.dictionaryapi.dev/media/pronunciations/en/pancake-us.mp3', 1, '2026-06-01 14:48:14'),
(4365, 'panda', 1, '/ˈpændə/', 'The red panda (Ailurus fulgens), a small raccoon-like animal of northeast Asia with reddish fur and a long, ringed tail.', '大貓熊、貓熊', 'https://api.dictionaryapi.dev/media/pronunciations/en/panda-1-us.mp3', 1, '2026-06-01 14:48:14'),
(4366, 'pane', 1, '/peɪn/', 'An individual sheet of glass in a window, door, etc.', '窗格、窗玻璃', 'https://api.dictionaryapi.dev/media/pronunciations/en/pane-us.mp3', 1, '2026-06-01 14:48:14'),
(4367, 'panel', 1, '/ˈpænəl/', 'A (usually) rectangular section of a surface, or of a covering or of a wall, fence etc.', '嵌板、儀表板、專門小組', 'https://api.dictionaryapi.dev/media/pronunciations/en/panel-us.mp3', 1, '2026-06-01 14:48:14'),
(4368, 'panic', 1, '/ˈpænɪk/', 'Overpowering fright, often affecting groups of people or animals.', '恐慌、驚慌', 'https://api.dictionaryapi.dev/media/pronunciations/en/panic-us.mp3', 1, '2026-06-01 14:48:14'),
(4369, 'panic', 2, '/ˈpænɪk/', 'To feel overwhelming fear.', '使恐慌、驚慌失措', 'https://api.dictionaryapi.dev/media/pronunciations/en/panic-us.mp3', 1, '2026-06-01 14:48:14'),
(4370, 'panorama', 1, '/ˌpæ.nəˈɹæ.mə/', 'An unbroken view of an entire surrounding area.', '全景、綜論', 'https://dictionaryapi.dev/panorama', 1, '2026-06-01 14:48:14'),
(4371, 'pants', 1, '', '(Manchester) An outer garment that covers the body from the waist downwards, covering each leg separately, usually as far as the ankles; trousers.', '褲子、長褲', 'https://api.dictionaryapi.dev/media/pronunciations/en/pants-au.mp3', 1, '2026-06-01 14:48:14'),
(4372, 'papa', 1, '/pəˈpɑː/', 'Dad, daddy, father; a familiar or old-fashioned term of address to one’s father.', '爸爸', 'https://api.dictionaryapi.dev/media/pronunciations/en/papa-us.mp3', 1, '2026-06-01 14:48:14'),
(4373, 'papaya', 1, '/pəˈpaɪə/', 'A tropical American evergreen tree, Carica papaya, having large, yellow, edible fruit', '木瓜', 'https://api.dictionaryapi.dev/media/pronunciations/en/papaya-uk.mp3', 1, '2026-06-01 14:48:14'),
(4374, 'paper', 1, '/ˈpeɪpə/', 'A sheet material used for writing on or printing on (or as a non-waterproof container), usually made by draining cellulose fibres from a suspension in water.', '紙、論文、報紙', 'https://api.dictionaryapi.dev/media/pronunciations/en/paper-uk.mp3', 1, '2026-06-01 14:48:14'),
(4375, 'parachute', 1, '/ˈpæɹəʃuːt/', 'A device, generally constructed from fabric, that is designed to employ air resistance to control the fall of an object.', '降落傘', 'https://api.dictionaryapi.dev/media/pronunciations/en/parachute-us.mp3', 1, '2026-06-01 14:48:14'),
(4376, 'parade', 1, '/pəˈɹeɪd/', 'An organized procession consisting of a series of consecutive displays, performances, exhibits, etc. displayed by moving down a street past a crowd of spectators.', '遊行、閱兵', 'https://api.dictionaryapi.dev/media/pronunciations/en/parade-us.mp3', 1, '2026-06-01 14:48:14'),
(4377, 'paradise', 1, '/ˈpæ.ɹə.daɪs/', 'The place where sanctified souls are believed to live after death.', '天堂、樂園', 'https://api.dictionaryapi.dev/media/pronunciations/en/paradise-us.mp3', 1, '2026-06-01 14:48:14'),
(4378, 'paradoxically', 4, '', 'In a paradoxical manner; so as to create a paradox.', '自相矛盾地、似非而是地', 'https://api.dictionaryapi.dev/media/pronunciations/en/paradoxically-us.mp3', 1, '2026-06-01 14:48:14'),
(4379, 'paragon', 1, '/ˈpæɹəɡən/', 'A person of preeminent qualities, who acts as a pattern or model for others.', '模範、典範、完人', 'https://api.dictionaryapi.dev/media/pronunciations/en/paragon-uk.mp3', 1, '2026-06-01 14:48:14'),
(4380, 'paragraph', 1, '/ˈpæɹəɡɹɑːf/', 'A passage in text that is about a different subject from the preceding text, marked by commencing on a new line, the first line sometimes being indented.', '段落、節', 'https://api.dictionaryapi.dev/media/pronunciations/en/paragraph-us.mp3', 1, '2026-06-01 14:48:14'),
(4381, 'paralyze', 2, '', 'To afflict with paralysis.', '使癱瘓、使麻痺、使無法運作', 'https://dictionaryapi.dev/paralyze', 1, '2026-06-01 14:48:14'),
(4382, 'paramount', 1, '/ˈpa.ɹə.maʊnt/', 'A chief or superior.', '至高無上、最高權威（名詞用法）', 'https://api.dictionaryapi.dev/media/pronunciations/en/paramount-uk.mp3', 1, '2026-06-01 14:48:14'),
(4383, 'paramount', 3, '/ˈpa.ɹə.maʊnt/', 'Supreme; highest; chief.', '至高無上的、最重要的', 'https://api.dictionaryapi.dev/media/pronunciations/en/paramount-uk.mp3', 1, '2026-06-01 14:48:14'),
(4384, 'pardon', 1, '/ˈpɑɹ.dən/', 'Forgiveness for an offence.', '原諒、寬恕、赦免（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/pardon-us.mp3', 1, '2026-06-01 14:48:14'),
(4385, 'pardon', 2, '/ˈpɑɹ.dən/', 'To forgive (a person).', '原諒、寬恕、赦免（動詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/pardon-us.mp3', 1, '2026-06-01 14:48:14'),
(4386, 'parent', 1, '/ˈpɛəɹənt/', 'One of the two persons from whom one is immediately biologically descended; a mother or father.', '雙親之一、父母', 'https://api.dictionaryapi.dev/media/pronunciations/en/parent-us.mp3', 1, '2026-06-01 14:48:14'),
(4387, 'park', 1, '[paːk]', 'An area of land set aside for environment preservation or recreation.', '公園、停車場', 'https://api.dictionaryapi.dev/media/pronunciations/en/park-au.mp3', 1, '2026-06-01 14:48:14'),
(4388, 'park', 2, '[paːk]', 'To bring (something such as a vehicle) to a halt or store in a specified place.', '停車', 'https://api.dictionaryapi.dev/media/pronunciations/en/park-au.mp3', 1, '2026-06-01 14:48:14'),
(4389, 'parking', 1, '/ˈpɑːkɪŋ/', 'The action of the verb to park.', '停車、停車場（名詞）', 'https://dictionaryapi.dev/parking', 1, '2026-06-01 14:48:14'),
(4390, 'parlor', 1, '/ˈpɑːlə/', 'The living room of a house, or a room for entertaining guests; a room for talking; a sitting-room or drawing room', '客廳、接待室、特定店鋪（如美容院）', 'https://api.dictionaryapi.dev/media/pronunciations/en/parlor-us.mp3', 1, '2026-06-01 14:48:14'),
(4391, 'parrot', 1, '/ˈpæɹət/', 'A kind of bird, many species of which are colourful and able to mimic human speech, of the order Psittaciformes or (narrowly) of the family Psittacidae.', '鸚鵡', 'https://api.dictionaryapi.dev/media/pronunciations/en/parrot-us.mp3', 1, '2026-06-01 14:48:14'),
(4392, 'part', 1, '/pɐːt/', 'A portion; a component.', '部分、零件、角色、零件', 'https://api.dictionaryapi.dev/media/pronunciations/en/part-us.mp3', 1, '2026-06-01 14:48:14'),
(4393, 'part-time', 3, '', 'For, during, or involving less than the normal time for some activity, especially the number of hours an employee works.', '兼職的、部分的', 'https://dictionaryapi.dev/part-time', 1, '2026-06-01 14:48:14'),
(4394, 'part-time', 4, '', 'For, during, or involving less than the normal time for some activity, especially the number of hours an employee works.', '兼職地', 'https://dictionaryapi.dev/part-time', 1, '2026-06-01 14:48:14'),
(4395, 'partial', 3, '/ˈpɑːʃəl/', 'Existing as a part or portion; incomplete', '部分的、偏袒的', 'https://dictionaryapi.dev/partial', 1, '2026-06-01 14:48:14'),
(4396, 'partially', 4, '/ˈpɑːʃəli/', 'To a partial degree or extent, incompletely.', '部分地、不完全地', 'https://dictionaryapi.dev/partially', 1, '2026-06-01 14:48:14'),
(4397, 'participant', 1, '/pɑːˈtɪsɪpənt/', 'One who participates.', '參與者、分享者', 'https://dictionaryapi.dev/participant', 1, '2026-06-01 14:48:14'),
(4398, 'participate', 2, '/pɑːˈtɪsɪpeɪt/', 'To join in, to take part, to involve oneself (in something).', '參與、參加', 'https://api.dictionaryapi.dev/media/pronunciations/en/participate-us.mp3', 1, '2026-06-01 14:48:14'),
(4399, 'particular', 3, '/pəˈtɪkjələ/', 'Pertaining only to a part of something; partial.', '特定的、挑剔的、特有的', 'https://api.dictionaryapi.dev/media/pronunciations/en/particular-us.mp3', 1, '2026-06-01 14:48:14'),
(4400, 'partner', 1, '/ˈpɐːtnə/', 'Someone who is associated with another in a common activity or interest.', '夥伴、合夥人、配偶', 'https://api.dictionaryapi.dev/media/pronunciations/en/partner-us.mp3', 1, '2026-06-01 14:48:14'),
(4401, 'partnership', 1, '', 'The state of being associated with a partner.', '夥伴關係、合夥關係', 'https://api.dictionaryapi.dev/media/pronunciations/en/partnership-au.mp3', 1, '2026-06-01 14:48:14'),
(4402, 'party', 1, '/ˈpɑ(ː)ɾi/', 'A person or group of people constituting a particular side in a contract or legal action.', '派對、政黨、當事人、一行人', 'https://api.dictionaryapi.dev/media/pronunciations/en/party-ca.mp3', 1, '2026-06-01 14:48:14'),
(4403, 'pass', 1, '[pʰäːs]', 'To change place.', '通行證、及格、傳球、山隘', 'https://api.dictionaryapi.dev/media/pronunciations/en/pass-us.mp3', 1, '2026-06-01 14:48:14'),
(4404, 'pass', 2, '[pʰäːs]', 'To change place.', '通過、經過、及格、傳遞', 'https://api.dictionaryapi.dev/media/pronunciations/en/pass-us.mp3', 1, '2026-06-01 14:48:14'),
(4405, 'passage', 1, '/ˈpæsɪd͡ʒ/', 'A paragraph or section of text or music with particular meaning.', '通道、走廊、段落、經過', 'https://api.dictionaryapi.dev/media/pronunciations/en/passage-1-us.mp3', 1, '2026-06-01 14:48:14'),
(4406, 'passenger', 1, '/ˈpæsənd͡ʒə/', 'One who rides or travels in a vehicle, but who does not operate it and is not a member of the crew.', '乘客、旅客', 'https://api.dictionaryapi.dev/media/pronunciations/en/passenger-us.mp3', 1, '2026-06-01 14:48:14'),
(4407, 'passerby', 1, '', 'A person who is passing by (that is, walking past).', '路人、過路客', 'https://dictionaryapi.dev/passerby', 1, '2026-06-01 14:48:14'),
(4408, 'passion', 1, '[ˈpʰæʃən]', 'Any great, strong, powerful emotion, especially romantic love or extreme hate.', '熱情、激情、酷愛', 'https://api.dictionaryapi.dev/media/pronunciations/en/passion-us.mp3', 1, '2026-06-01 14:48:14'),
