(4581, 'plan', 2, '/plæn/', 'To design (a building, machine, etc.).', '計劃、打算、設計', 'https://api.dictionaryapi.dev/media/pronunciations/en/plan-us.mp3', 1, '2026-06-01 14:48:14'),
(4582, 'plane', 1, '/pleɪn/', 'A level or flat surface.', '飛機、平面', 'https://api.dictionaryapi.dev/media/pronunciations/en/plane-us.mp3', 1, '2026-06-01 14:48:14'),
(4583, 'planet', 1, '/ˈplænət/', 'Each of the seven major bodies which move relative to the fixed stars in the night sky—the Moon, Mercury, Venus, the Sun, Mars, Jupiter and Saturn.', '行星', 'https://api.dictionaryapi.dev/media/pronunciations/en/planet-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(4584, 'planetary', 3, '/ˈplæ.nə.ˌtɛr.i/', 'Of, or relating to planets, or the orbital motion of planets.', '行星的、在全球範圍的', 'https://api.dictionaryapi.dev/media/pronunciations/en/planetary-uk.mp3', 1, '2026-06-01 14:48:14'),
(4585, 'planning', 1, '/ˈplænɪŋ/', 'Action of the verb to plan.', '計畫、規劃', 'https://dictionaryapi.dev/planning', 1, '2026-06-01 14:48:14'),
(4586, 'plant', 1, '/plænt/', 'An organism that is not an animal, especially an organism capable of photosynthesis. Typically a small or herbaceous organism of this kind, rather than a tree.', '植物、工廠、車間', 'https://api.dictionaryapi.dev/media/pronunciations/en/plant-uk.mp3', 1, '2026-06-01 14:48:14'),
(4587, 'plant', 2, '/plænt/', 'To place (a seed or plant) in soil or other substrate in order that it may live and grow.', '種植、栽種、安置', 'https://api.dictionaryapi.dev/media/pronunciations/en/plant-uk.mp3', 1, '2026-06-01 14:48:14'),
(4588, 'plantation', 1, '/plænˈteɪʃən/', 'A large farm; estate or area of land designated for agricultural growth. Often includes housing for the owner and workers.', '大農場、種植園', 'https://api.dictionaryapi.dev/media/pronunciations/en/plantation-us.mp3', 1, '2026-06-01 14:48:14'),
(4589, 'plaster', 1, '/ˈplastə/', 'A paste applied to the skin for healing or cosmetic purposes.', '熟石膏、灰泥、灰泥牆', 'https://api.dictionaryapi.dev/media/pronunciations/en/plaster-us.mp3', 1, '2026-06-01 14:48:14'),
(4590, 'plastic', 1, '/ˈplæstɪk/', 'A synthetic, solid, hydrocarbon-based polymer, whether thermoplastic or thermosetting.', '塑膠、塑膠製品', 'https://api.dictionaryapi.dev/media/pronunciations/en/plastic-us.mp3', 1, '2026-06-01 14:48:14'),
(4591, 'plastic', 3, '/ˈplæstɪk/', 'Capable of being moulded; malleable, flexible, pliant.', '塑膠製的、可塑的、虛假的', 'https://api.dictionaryapi.dev/media/pronunciations/en/plastic-us.mp3', 1, '2026-06-01 14:48:14'),
(4592, 'plate', 1, '/pleɪt/', 'A slightly curved but almost flat dish from which food is served or eaten.', '盤子、金屬板、車牌', 'https://api.dictionaryapi.dev/media/pronunciations/en/plate-au.mp3', 1, '2026-06-01 14:48:14'),
(4593, 'platform', 1, '/ˈplætfɔːm/', 'A raised stage from which speeches are made and on which musical and other performances are made.', '平台、講台、月台、政綱', 'https://api.dictionaryapi.dev/media/pronunciations/en/platform-us.mp3', 1, '2026-06-01 14:48:14'),
(4594, 'Plato', 1, '', 'N/A', '柏拉圖', NULL, 1, '2026-06-01 14:48:14'),
(4595, 'play', 1, '/pleɪ/', 'Activity for amusement only, especially among the young.', '遊戲、劇本、比賽、播放（名詞用法）', 'https://api.dictionaryapi.dev/media/pronunciations/en/play-us.mp3', 1, '2026-06-01 14:48:14'),
(4596, 'play', 2, '/pleɪ/', 'To act in a manner such that one has fun; to engage in activities expressly for the purpose of recreation or entertainment.', '玩、玩耍、演奏、播放、打球', 'https://api.dictionaryapi.dev/media/pronunciations/en/play-us.mp3', 1, '2026-06-01 14:48:14'),
(4597, 'playground', 1, '/ˈpleɪɡɹaʊnd/', '(outdoors) A large open space for children to play on, usually having dedicated play equipment (such as swings and slides).', '遊樂場、兒童遊戲場', 'https://api.dictionaryapi.dev/media/pronunciations/en/playground-us.mp3', 1, '2026-06-01 14:48:14'),
(4598, 'playmate', 1, '', 'A companion for someone (especially a child) to play with.', '玩伴', 'https://dictionaryapi.dev/playmate', 1, '2026-06-01 14:48:14'),
(4599, 'playwright', 1, '/ˈpleɪˌɹaɪt/', 'A writer and creator of theatrical plays.', '劇作家', 'https://api.dictionaryapi.dev/media/pronunciations/en/playwright-us.mp3', 1, '2026-06-01 14:48:14'),
(4600, 'plea', 1, '/pliː/', 'An appeal, petition, urgent prayer or entreaty.', '懇求、辯解、答辯、抗辯', 'https://api.dictionaryapi.dev/media/pronunciations/en/plea-uk.mp3', 1, '2026-06-01 14:48:14'),
(4601, 'pleasant', 3, '/ˈplɛzənt/', 'Giving pleasure; pleasing in manner.', '令人愉快的、舒適的', 'https://api.dictionaryapi.dev/media/pronunciations/en/pleasant-us.mp3', 1, '2026-06-01 14:48:14'),
(4602, 'please', 2, '/pliːz/', 'To make happy or satisfy; to give pleasure to.', '使高興、使滿意、討好', 'https://api.dictionaryapi.dev/media/pronunciations/en/please-uk.mp3', 1, '2026-06-01 14:48:14'),
(4603, 'pleased', 3, '/pliːzd/', 'Happy, content', '高興的、滿意的', 'https://api.dictionaryapi.dev/media/pronunciations/en/pleased-us.mp3', 1, '2026-06-01 14:48:14'),
(4604, 'pleasure', 1, '/ˈplɛʒə/', 'A state of being pleased or contented; gratification.', '快樂、娛樂、榮幸', 'https://api.dictionaryapi.dev/media/pronunciations/en/pleasure-us.mp3', 1, '2026-06-01 14:48:14'),
(4605, 'pledge', 2, '/plɛdʒ/', 'To make a solemn promise (to do something).', '發誓、保證、使投入', 'https://api.dictionaryapi.dev/media/pronunciations/en/pledge-us.mp3', 1, '2026-06-01 14:48:14'),
(4606, 'plentiful', 3, '/ˈplɛntɪfl̩/', 'Existing in large number or ample amount.', '豐富的、充足的', 'https://api.dictionaryapi.dev/media/pronunciations/en/plentiful-us.mp3', 1, '2026-06-01 14:48:14'),
(4607, 'plenty', 1, '/ˈplɛnti/', 'A more-than-adequate amount.', '豐富、充足、大量', 'https://api.dictionaryapi.dev/media/pronunciations/en/plenty-us.mp3', 1, '2026-06-01 14:48:14'),
(4608, 'plot', 1, '/plɒt/', '(authorship) The course of a story, comprising a series of incidents which are gradually unfolded, sometimes by unexpected means.', '情節、陰謀、小塊土地', 'https://api.dictionaryapi.dev/media/pronunciations/en/plot-us.mp3', 1, '2026-06-01 14:48:14'),
(4609, 'plot', 2, '/plɒt/', 'To conceive (a crime, etc).', '密謀、策劃、繪製...的圖', 'https://api.dictionaryapi.dev/media/pronunciations/en/plot-us.mp3', 1, '2026-06-01 14:48:14'),
(4610, 'plow', 2, '', 'To use a plough on to prepare for planting.', '犁地、耕地、破浪前進', 'https://dictionaryapi.dev/plow', 1, '2026-06-01 14:48:14'),
(4611, 'plug', 1, '/plʌɡ/', 'A pronged connecting device which fits into a mating socket, especially an electrical one.', '插頭、塞子、消防栓', 'https://api.dictionaryapi.dev/media/pronunciations/en/plug-us.mp3', 1, '2026-06-01 14:48:14'),
(4612, 'plumber', 1, '/ˈplʌmə/', 'One who works in or with lead.', '水電工、水管工人', 'https://api.dictionaryapi.dev/media/pronunciations/en/plumber-uk.mp3', 1, '2026-06-01 14:48:14'),
(4613, 'plus', 1, '/plʌs/', 'A positive quantity.', '正號、加號、好處', 'https://api.dictionaryapi.dev/media/pronunciations/en/plus-us.mp3', 1, '2026-06-01 14:48:14'),
(4614, 'plus', 3, '/plʌs/', 'Being positive rather than negative or zero.', '正的、加的、有利的', 'https://api.dictionaryapi.dev/media/pronunciations/en/plus-us.mp3', 1, '2026-06-01 14:48:14'),
