(4629, 'policy', 1, '/ˈpɒləsi/', 'A principle of behaviour, conduct etc. thought to be desirable or necessary, especially as formally expressed by a government or other authoritative body.', '政策、方針、保險單', 'https://api.dictionaryapi.dev/media/pronunciations/en/policy-us.mp3', 1, '2026-06-01 14:48:14'),
(4630, 'polish', 2, '/ˈpɒlɪʃ/', 'To shine; to make a surface very smooth or shiny by rubbing, cleaning, or grinding.', '擦亮、磨光、潤色', 'https://api.dictionaryapi.dev/media/pronunciations/en/polish-us.mp3', 1, '2026-06-01 14:48:14'),
(4631, 'Polish', 3, '/ˈpɒlɪʃ/', 'A substance used to polish.', '波蘭的、波蘭人的、波蘭語的', 'https://api.dictionaryapi.dev/media/pronunciations/en/polish-us.mp3', 1, '2026-06-01 14:48:14'),
(4632, 'polite', 3, '/pəˈlaɪt/', 'Well-mannered, civilized.', '有禮貌的、客氣的、文雅的', 'https://api.dictionaryapi.dev/media/pronunciations/en/polite.mp3', 1, '2026-06-01 14:48:14'),
(4633, 'political', 3, '/pəˈlɪtɪkəl/', 'Concerning or relating to politics, the art and process of governing.', '政治的、黨派的', 'https://api.dictionaryapi.dev/media/pronunciations/en/political-us.mp3', 1, '2026-06-01 14:48:14'),
(4634, 'politician', 1, '/ˈpɒl.ɪ.tɪʃ.ən/', 'One engaged in politics, especially an elected or appointed government official.', '政治人物、政客', 'https://api.dictionaryapi.dev/media/pronunciations/en/politician-us.mp3', 1, '2026-06-01 14:48:14'),
