(4643, 'pony', 1, '', 'A small horse; specifically, any of several small breeds of horse under 14.2 hands at the withers.', '小型馬、矮馬', 'https://api.dictionaryapi.dev/media/pronunciations/en/pony-au.mp3', 1, '2026-06-01 14:48:14'),
(4644, 'pool', 1, '/pul/', 'A small and rather deep collection of (usually) fresh water, as one supplied by a spring, or occurring in the course of a stream; a reservoir for water.', '水池、游泳池、撞球、共同資金', 'https://api.dictionaryapi.dev/media/pronunciations/en/pool-uk.mp3', 1, '2026-06-01 14:48:14'),
(4645, 'poor', 3, '/poː/', 'With no or few possessions or money, particularly in relation to contemporaries who do have them.', '貧窮的、可憐的、品質差的', 'https://api.dictionaryapi.dev/media/pronunciations/en/poor-uk.mp3', 1, '2026-06-01 14:48:14'),
