(4750, 'price', 1, '/pɹaɪs/', 'The cost required to gain possession of something.', '價格、代價、代價', 'https://api.dictionaryapi.dev/media/pronunciations/en/price-uk.mp3', 1, '2026-06-01 14:48:14'),
(4751, 'price', 2, '/pɹaɪs/', 'To determine the monetary value of (an item); to put a price on.', '定價、標價', 'https://api.dictionaryapi.dev/media/pronunciations/en/price-uk.mp3', 1, '2026-06-01 14:48:14'),
(4752, 'pride', 1, '/pɹaɪd/', 'The quality or state of being proud; an unreasonable overestimation of one\'s own superiority in terms of talents, looks, wealth, importance etc., which manifests itself in lofty airs, distance, reserve and often contempt of others.', '驕傲、自豪、引以為榮的人或物', 'https://api.dictionaryapi.dev/media/pronunciations/en/pride-us.mp3', 1, '2026-06-01 14:48:14'),
(4753, 'pride', 2, '/pɹaɪd/', 'To take or experience pride in something; to be proud of it.', '以...自豪、自誇', 'https://api.dictionaryapi.dev/media/pronunciations/en/pride-us.mp3', 1, '2026-06-01 14:48:14'),
(4754, 'primary', 3, '/ˈpɹɒeməɹi/', 'First or earliest in a group or series.', '主要的、首要的、初級的', 'https://api.dictionaryapi.dev/media/pronunciations/en/primary-us.mp3', 1, '2026-06-01 14:48:14'),
(4755, 'prime', 3, '/pɹaɪ̯m/', 'First in importance, degree, or rank.', '主要的、首要的、最佳的', 'https://api.dictionaryapi.dev/media/pronunciations/en/prime-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4756, 'primitive', 3, '/ˈpɹɪmɪtɪv/', 'Of or pertaining to the beginning or origin, or to early times; original; primordial; primeval; first.', '原始的、遠古的、落後的', 'https://api.dictionaryapi.dev/media/pronunciations/en/primitive-us.mp3', 1, '2026-06-01 14:48:14'),
(4757, 'prince', 1, '/pɹɪns/', 'A (male) ruler, a sovereign; a king, monarch.', '王子、親王', 'https://api.dictionaryapi.dev/media/pronunciations/en/prince-us.mp3', 1, '2026-06-01 14:48:14'),
(4758, 'princess', 1, '/pɹɪnˈsɛs/', 'A female member of a royal family other than a queen, especially a daughter or granddaughter.', '公主、王妃', 'https://api.dictionaryapi.dev/media/pronunciations/en/princess-us.mp3', 1, '2026-06-01 14:48:14'),
(4759, 'principal', 1, '/ˈpɹɪnsəpəl/', 'The money originally invested or loaned, on which basis interest and returns are calculated.', '校長、主事者、主嫌', 'https://api.dictionaryapi.dev/media/pronunciations/en/principal-au.mp3', 1, '2026-06-01 14:48:14'),
(4760, 'principal', 3, '/ˈpɹɪnsəpəl/', 'Primary; most important; first level in importance.', '主要的、首要的', 'https://api.dictionaryapi.dev/media/pronunciations/en/principal-au.mp3', 1, '2026-06-01 14:48:14'),
(4761, 'principally', 4, '', 'In a primary manner; pertaining to the principal of a matter.', '主要地、大部分', 'https://api.dictionaryapi.dev/media/pronunciations/en/principally-us.mp3', 1, '2026-06-01 14:48:14'),
(4762, 'principle', 1, '/ˈpɹɪnsəpəl/', 'A fundamental assumption or guiding belief.', '原則、原理、準則、道義', 'https://api.dictionaryapi.dev/media/pronunciations/en/principle-us.mp3', 1, '2026-06-01 14:48:14'),
(4763, 'print', 1, '/pɹɪnt/', 'Books and other material created by printing presses, considered collectively or as a medium.', '印刷品、印出來的字、字體、腳印', 'https://api.dictionaryapi.dev/media/pronunciations/en/print-us.mp3', 1, '2026-06-01 14:48:14'),
(4764, 'print', 2, '/pɹɪnt/', 'To produce one or more copies of a text or image on a surface, especially by machine; often used with out or off: print out, print off.', '印刷、出版、刊登、沖洗（照片）', 'https://api.dictionaryapi.dev/media/pronunciations/en/print-us.mp3', 1, '2026-06-01 14:48:14'),
(4765, 'printer', 1, '', 'One who makes prints.', '印表機、印刷工', 'https://api.dictionaryapi.dev/media/pronunciations/en/printer-au.mp3', 1, '2026-06-01 14:48:14'),
(4766, 'priority', 1, '/pɹaɪˈɒɹɨti/', 'An item\'s relative importance.', '優先、優先權、優先考慮的事', 'https://dictionaryapi.dev/priority', 1, '2026-06-01 14:48:14'),
(4767, 'prison', 1, '/ˈpɹɪzən/', 'A place or institution of confinement, especially of long-term confinement for those convicted of serious crimes or otherwise considered undesirable by the government.', '監獄、牢房', 'https://api.dictionaryapi.dev/media/pronunciations/en/prison-us.mp3', 1, '2026-06-01 14:48:14'),
(4768, 'privacy', 1, '/ˈpɹaɪv.ə.sɪ/', 'The state of being secluded from the presence, sight, or knowledge of others.', '隱私、私生活、秘密', 'https://dictionaryapi.dev/privacy', 1, '2026-06-01 14:48:14'),
(4769, 'private', 3, '/ˈpɹaɪvət/', 'Belonging to, concerning, or accessible only to an individual person or a specific group.', '私人的、私立的、秘密的', 'https://api.dictionaryapi.dev/media/pronunciations/en/private-us.mp3', 1, '2026-06-01 14:48:14'),
(4770, 'privately', 4, '/ˈpɹaɪvətli/', 'In a private manner.', '私下地、秘密地', 'https://dictionaryapi.dev/privately', 1, '2026-06-01 14:48:14'),
(4771, 'privilege', 1, '/ˈpɹɪv(ɪ)lɪdʒ/', '(ecclesiastical law) An exemption from certain laws granted by the Pope.', '特權、榮幸、恩典', 'https://api.dictionaryapi.dev/media/pronunciations/en/privilege-us.mp3', 1, '2026-06-01 14:48:14'),
(4772, 'prize', 1, '/pɹaɪz/', 'That which is taken from another; something captured; a thing seized by force, stratagem, or superior power.', '獎品、獎金、難能可貴的人事物', 'https://api.dictionaryapi.dev/media/pronunciations/en/prize-1-us.mp3', 1, '2026-06-01 14:48:14'),
(4773, 'prize', 2, '/pɹaɪz/', 'That which is taken from another; something captured; a thing seized by force, stratagem, or superior power.', '珍視、高度評價', 'https://api.dictionaryapi.dev/media/pronunciations/en/prize-1-us.mp3', 1, '2026-06-01 14:48:14'),
(4774, 'probable', 3, '/ˈpɹɒbəbl̩/', 'Likely or most likely to be true.', '很可能的、大概的', 'https://api.dictionaryapi.dev/media/pronunciations/en/probable-us.mp3', 1, '2026-06-01 14:48:14'),
(4775, 'probe', 2, '/pɹəʊb/', 'To explore, investigate, or question', '探查、探測、調查、用探針檢查', 'https://api.dictionaryapi.dev/media/pronunciations/en/probe-uk.mp3', 1, '2026-06-01 14:48:14'),
(4776, 'problem', 1, '/ˈpɹɒbləm/', 'A difficulty that has to be resolved or dealt with.', '問題、難題', 'https://api.dictionaryapi.dev/media/pronunciations/en/problem-us.mp3', 1, '2026-06-01 14:48:14'),
(4777, 'procedure', 1, '/pɹəˈsiːdʒə/', 'A particular method for performing a task.', '程序、步驟、手續、訴訟程序', 'https://api.dictionaryapi.dev/media/pronunciations/en/procedure-us.mp3', 1, '2026-06-01 14:48:14'),
(4778, 'proceed', 2, '/pɹəˈsiːd/', 'To move, pass, or go forward or onward; to advance; to carry on', '繼續進行、前進、著手', 'https://api.dictionaryapi.dev/media/pronunciations/en/proceed-us.mp3', 1, '2026-06-01 14:48:14'),
(4779, 'proceeding', 1, '/pɹəˈsiːdɪŋ/', 'The act of one who proceeds, or who prosecutes a design or transaction', '訴訟、訴訟程序、事項、會議記錄', 'https://api.dictionaryapi.dev/media/pronunciations/en/proceeding-us.mp3', 1, '2026-06-01 14:48:14'),
(4780, 'process', 1, '/ˈpɹoʊsɛs/', 'A series of events which produce a result (the product).', '過程、進程、工序、製作法', 'https://api.dictionaryapi.dev/media/pronunciations/en/process-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4781, 'process', 2, '/ˈpɹoʊsɛs/', 'To perform a particular process on a thing.', '處理、加工、辦理', 'https://api.dictionaryapi.dev/media/pronunciations/en/process-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4782, 'processing', 1, '/ˈpɹəʊsɛsɪŋ/', 'The action of the verb to process.', '加工、處理', 'https://api.dictionaryapi.dev/media/pronunciations/en/processing-us.mp3', 1, '2026-06-01 14:48:14'),
(4783, 'proclamation', 1, '/ˌpɹɒkləˈmeɪʃən/', 'A statement which is proclaimed; formal public announcement.', '公告、宣言、發表', 'https://api.dictionaryapi.dev/media/pronunciations/en/proclamation-us.mp3', 1, '2026-06-01 14:48:14'),
(4784, 'produce', 2, '', 'To yield, make or manufacture; to generate.', '生產、製造、出產、上映', 'https://api.dictionaryapi.dev/media/pronunciations/en/produce-1-au.mp3', 1, '2026-06-01 14:48:14'),
(4785, 'product', 1, '/ˈpɹɒd.əkt/', 'A commodity offered for sale.', '產品、產物、乘積', 'https://dictionaryapi.dev/product', 1, '2026-06-01 14:48:14'),
(4786, 'production', 1, '/pɹəˈdʌkʃən/', 'The act of producing, making or creating something.', '生產、產量、製作、產品', 'https://api.dictionaryapi.dev/media/pronunciations/en/production-uk.mp3', 1, '2026-06-01 14:48:14'),
(4787, 'productive', 3, '/pɹəˈdʌktɪv/', 'Capable of producing something, especially in abundance; fertile.', '多產的、富有成效的、有生產力的', 'https://dictionaryapi.dev/productive', 1, '2026-06-01 14:48:14'),
(4788, 'productivity', 1, '/ˌpɹɒdʌkˈtɪvəti/', 'The state of being productive, fertile or efficient', '生產力、生產率', 'https://api.dictionaryapi.dev/media/pronunciations/en/productivity-us.mp3', 1, '2026-06-01 14:48:14'),
(4789, 'profess', 2, '/pɹəˈfɛs/', 'To administer the vows of a religious order to (someone); to admit to a religious order. (Chiefly in passive.)', '聲稱、公開信奉、坦白', 'https://dictionaryapi.dev/profess', 1, '2026-06-01 14:48:14'),
(4790, 'profession', 1, '/pɹəˈfɛʃən/', 'A declaration of belief, faith or one\'s opinion, whether genuine or pretended.', '職業、專業、同行', 'https://api.dictionaryapi.dev/media/pronunciations/en/profession-uk.mp3', 1, '2026-06-01 14:48:14'),
(4791, 'professional', 1, '/pɹəˈfɛʃənəl/', 'A person who belongs to a profession', '專業人員、職業選手', 'https://api.dictionaryapi.dev/media/pronunciations/en/professional-us.mp3', 1, '2026-06-01 14:48:14'),
(4792, 'professional', 3, '/pɹəˈfɛʃənəl/', 'Of, pertaining to, or in accordance with the (usually high) standards of a profession.', '專業的、職業的', 'https://api.dictionaryapi.dev/media/pronunciations/en/professional-us.mp3', 1, '2026-06-01 14:48:14'),
(4793, 'professor', 1, '/pɹəˈfɛsə/', 'The most senior rank for an academic at a university or similar institution, informally also known as \"full professor.\" Abbreviated Prof.', '教授', 'https://api.dictionaryapi.dev/media/pronunciations/en/professor-uk.mp3', 1, '2026-06-01 14:48:14'),
(4794, 'proficient', 3, '/pɹəˈfɪʃ.ənt/', 'Good at something; skilled; fluent; practiced, especially in relation to a task or skill.', '精通的、熟練的', 'https://api.dictionaryapi.dev/media/pronunciations/en/proficient-us.mp3', 1, '2026-06-01 14:48:14'),
(4795, 'profile', 1, '/ˈpɹəʊfaɪl/', 'The outermost shape, view, or edge of an object.', '側面像、輪廓、簡介、形象', 'https://dictionaryapi.dev/profile', 1, '2026-06-01 14:48:14'),
(4796, 'profit', 1, '/ˈpɹɒfɪt/', 'Total income or cash flow minus expenditures. The money or other benefit a non-governmental organization or individual receives in exchange for products and services sold at an advertised price.', '利潤、收益、好處', 'https://api.dictionaryapi.dev/media/pronunciations/en/profit-us.mp3', 1, '2026-06-01 14:48:14'),
(4797, 'profit', 2, '/ˈpɹɒfɪt/', 'To benefit (somebody), be of use to (somebody).', '獲利、得益、有益於', 'https://api.dictionaryapi.dev/media/pronunciations/en/profit-us.mp3', 1, '2026-06-01 14:48:14'),
(4798, 'profitable', 3, '/ˈpɹɒfɪtəbl̩/', 'Producing a profit.', '有利可圖的、賺錢的、有益的', 'https://api.dictionaryapi.dev/media/pronunciations/en/profitable-us.mp3', 1, '2026-06-01 14:48:14'),
(4799, 'program', 1, '/ˈpɹoʊˌɡɹæm/', 'A set of structured activities.', '節目、計畫、程式、課程', 'https://api.dictionaryapi.dev/media/pronunciations/en/program-us.mp3', 1, '2026-06-01 14:48:14'),
(4800, 'program', 2, '/ˈpɹoʊˌɡɹæm/', 'To enter a program or other instructions into (a computer or other electronic device) to instruct it to do a particular task.', '為（電腦）編寫程式、規劃', 'https://api.dictionaryapi.dev/media/pronunciations/en/program-us.mp3', 1, '2026-06-01 14:48:14'),
(4801, 'progress', 1, '/ˈpɹɒɡɹɛs/', 'Movement or advancement through a series of events, or points in time; development through time.', '進步、進展、前進', 'https://api.dictionaryapi.dev/media/pronunciations/en/progress-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4802, 'progress', 2, '/ˈpɹɒɡɹɛs/', 'Movement or advancement through a series of events, or points in time; development through time.', '進步、進展、前進', 'https://api.dictionaryapi.dev/media/pronunciations/en/progress-1-uk.mp3', 1, '2026-06-01 14:48:14'),
(4803, 'progressive', 3, '/pɹəˈɡɹɛsɪv/', 'Favouring or promoting progress; advanced.', '進步的、先進的、漸進的', 'https://dictionaryapi.dev/progressive', 1, '2026-06-01 14:48:14'),
(4804, 'prohibit', 2, '/pɹəʊˈhɪbɪt/', 'To forbid, disallow, or proscribe officially; to make illegal or illicit.', '禁止、阻止、不准', 'https://api.dictionaryapi.dev/media/pronunciations/en/prohibit-us.mp3', 1, '2026-06-01 14:48:14'),
(4805, 'prohibition', 1, '/ˌpɹəʊ(h)ɪˈbɪʃən/', 'An act of prohibiting, forbidding, disallowing, or proscribing something.', '禁止、禁令、禁酒時期', 'https://api.dictionaryapi.dev/media/pronunciations/en/prohibition-us.mp3', 1, '2026-06-01 14:48:14'),
(4806, 'project', 1, '', 'A planned endeavor, usually with a specific goal and accomplished in several steps or stages.', '計畫、專案、工程', 'https://dictionaryapi.dev/project', 1, '2026-06-01 14:48:14'),
(4807, 'project', 2, '', 'To extend beyond a surface.', '投射、投影、預測、規劃', 'https://dictionaryapi.dev/project', 1, '2026-06-01 14:48:14'),
(4808, 'projection', 1, '/pɹəˈdʒɛkʃən/', 'Something which projects, protrudes, juts out, sticks out, or stands out.', '投影、投射、預測、推估', 'https://dictionaryapi.dev/projection', 1, '2026-06-01 14:48:14'),
(4809, 'prominent', 3, '/ˈpɹɒmɪnənt/', 'Standing out, or projecting; jutting; protuberant', '著名的、顯著的、突出的', 'https://api.dictionaryapi.dev/media/pronunciations/en/prominent-us.mp3', 1, '2026-06-01 14:48:14'),
(4810, 'promise', 1, '/ˈpɹɒmɪs/', 'An oath or affirmation; a vow', '承諾、諾言、希望', 'https://api.dictionaryapi.dev/media/pronunciations/en/promise-us.mp3', 1, '2026-06-01 14:48:14'),
(4811, 'promise', 2, '/ˈpɹɒmɪs/', 'To commit to (some action or outcome), or to assure (a person) of such commitment; to make an oath or vow.', '答應、承諾、有...的希望', 'https://api.dictionaryapi.dev/media/pronunciations/en/promise-us.mp3', 1, '2026-06-01 14:48:14'),
(4812, 'promising', 3, '/ˈpɹɒmɪsɪŋ/', 'Showing promise, and likely to develop in a desirable fashion.', '有希望的、有前途的', '', 1, '2026-06-01 14:48:14'),
(4813, 'promote', 2, '/pɹəˈməʊt/', 'To raise (someone) to a more important, responsible, or remunerative job or rank.', '晉升、促進、推銷、推廣', 'https://api.dictionaryapi.dev/media/pronunciations/en/promote-us.mp3', 1, '2026-06-01 14:48:14'),
(4814, 'promotion', 1, '/pɹəˈməʊʃən/', 'An advancement in rank or position.', '升遷、晉升、促銷、推廣', 'https://api.dictionaryapi.dev/media/pronunciations/en/promotion-us.mp3', 1, '2026-06-01 14:48:14'),
(4815, 'prompt', 3, '/pɹɒmpt/', 'Quick; acting without delay.', '敏捷的、及時的、迅速的', 'https://api.dictionaryapi.dev/media/pronunciations/en/prompt-uk.mp3', 1, '2026-06-01 14:48:14'),
(4816, 'prone', 3, '/pɹəʊn/', 'Lying face downward.', '易於...的、有...傾向的、俯臥的', 'https://dictionaryapi.dev/prone', 1, '2026-06-01 14:48:14'),
(4817, 'pronoun', 1, '/ˈpɹəʊnaʊn/', '(grammar) A type of noun that refers anaphorically to another noun or noun phrase, but which cannot ordinarily be preceded by a determiner and rarely takes an attributive adjective. English examples include I, you, him, who, me, my, each other.', '代名詞', 'https://api.dictionaryapi.dev/media/pronunciations/en/pronoun-us.mp3', 1, '2026-06-01 14:48:14'),
(4818, 'pronounce', 2, '/pɹəˈnaʊns/', 'To declare formally, officially or ceremoniously.', '發音、宣告、宣判', 'https://api.dictionaryapi.dev/media/pronunciations/en/pronounce-us.mp3', 1, '2026-06-01 14:48:14'),
(4819, 'proof', 1, '/pɹʉːf/', 'An effort, process, or operation designed to establish or discover a fact or truth; an act of testing; a test; a trial.', '證據、證明、校樣', 'https://api.dictionaryapi.dev/media/pronunciations/en/proof-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(4820, 'proper', 3, '/ˈpɹɔp.ə/', '(heading) Suitable.', '適合的、適當的、正確的、體面的', 'https://api.dictionaryapi.dev/media/pronunciations/en/proper-us.mp3', 1, '2026-06-01 14:48:14'),
(4821, 'property', 1, '/ˈpɹɒp.ət.i/', 'Something that is owned.', '財產、資產、房產、特性', 'https://api.dictionaryapi.dev/media/pronunciations/en/property-us.mp3', 1, '2026-06-01 14:48:14'),
(4822, 'prophesy', 2, '/ˈpɹɒfɪsaɪ/', 'To speak or write with divine inspiration; to act as prophet.', '預言、預告', 'https://dictionaryapi.dev/prophesy', 1, '2026-06-01 14:48:14'),
(4823, 'proposal', 1, '/pɹəˈpəʊzəl/', 'Something which is proposed, or offered for consideration or acceptance', '提議、建議、提案', 'https://api.dictionaryapi.dev/media/pronunciations/en/proposal-uk.mp3', 1, '2026-06-01 14:48:14'),
(4824, 'propose', 2, '/pɹəˈpəʊz/', 'To suggest a plan, course of action, etc.', '提議、建議、求婚', 'https://api.dictionaryapi.dev/media/pronunciations/en/propose-us.mp3', 1, '2026-06-01 14:48:14'),
(4825, 'prose', 1, '/ˈpɹəʊz/', 'Language, particularly written language, not intended as poetry.', '散文、平凡的話語', 'https://api.dictionaryapi.dev/media/pronunciations/en/prose-us.mp3', 1, '2026-06-01 14:48:14'),
(4826, 'prosecution', 1, '/ˌpɹɑ.səˈkju.ʃən/', 'The act of prosecuting a scheme or endeavor.', '起訴、檢舉、實行', 'https://dictionaryapi.dev/prosecution', 1, '2026-06-01 14:48:14'),
(4827, 'prospect', 1, '/ˈpɹɒspɛkt/', 'The region which the eye overlooks at one time; view; scene; outlook.', '前景、前途、期望、景象', 'https://api.dictionaryapi.dev/media/pronunciations/en/prospect-uk-noun.mp3', 1, '2026-06-01 14:48:14'),
(4828, 'prosper', 2, '/ˈpɹɒspə(ɹ)/', 'To favor; to render successful.', '繁榮、興旺、成功', 'https://api.dictionaryapi.dev/media/pronunciations/en/prosper-uk.mp3', 1, '2026-06-01 14:48:14'),
(4829, 'prosperity', 1, '/pɹɒˈspɛɹ.ɪ.ti/', 'The condition of being prosperous, of having good fortune', '繁榮、興旺、成功', 'https://api.dictionaryapi.dev/media/pronunciations/en/prosperity-us.mp3', 1, '2026-06-01 14:48:14'),
