(5931, 'surrender', 2, '/səˈɹɛndəɹ/', 'To give up into the power, control, or possession of another.', '投降、自首、交出、放棄', 'https://api.dictionaryapi.dev/media/pronunciations/en/surrender-us.mp3', 1, '2026-06-01 14:48:14'),
(5932, 'surround', 2, '/səˈɹaʊnd/', 'To encircle something or simultaneously extend in all directions.', '圍繞、包圍、環繞', 'https://api.dictionaryapi.dev/media/pronunciations/en/surround-us.mp3', 1, '2026-06-01 14:48:14'),
(5933, 'surroundings', 1, '/səˈɹaʊndɪŋz/', 'An outlying area; area in proximity to something', '周圍環境、四周形勢', 'https://api.dictionaryapi.dev/media/pronunciations/en/surroundings-us.mp3', 1, '2026-06-01 14:48:14'),
(5934, 'survey', 1, '', 'The act of surveying; a general view.', '調查、測量、縱覽（名詞）', 'https://dictionaryapi.dev/survey', 1, '2026-06-01 14:48:14'),
(5935, 'survey', 2, '', 'To inspect, or take a view of; to view with attention, as from a high place; to overlook', '調查、測量、審視、勘測', 'https://dictionaryapi.dev/survey', 1, '2026-06-01 14:48:14'),
(5936, 'survival', 1, '/sɚˈvaɪvəl/', 'The fact or act of surviving; continued existence or life.', '倖存、生存、殘存', 'https://dictionaryapi.dev/survival', 1, '2026-06-01 14:48:14'),
(5937, 'survive', 2, '/səˈvʌɪv/', 'Of a person, to continue to live; to remain alive.', '活下來、倖存、比...活得長', 'https://api.dictionaryapi.dev/media/pronunciations/en/survive-us.mp3', 1, '2026-06-01 14:48:14'),
(5938, 'survivor', 1, '/sɚˈvaɪvɚ/', 'One who survives, especially one who survives a traumatic experience.', '倖存者、生還者', 'https://dictionaryapi.dev/survivor', 1, '2026-06-01 14:48:14'),
(5939, 'suspension', 1, '', 'The act of suspending, or the state of being suspended.', '暫停、中止、停職、懸吊', 'https://api.dictionaryapi.dev/media/pronunciations/en/suspension-au.mp3', 1, '2026-06-01 14:48:14'),
(5940, 'suspicion', 1, '/sə.ˈspɪ.ʃən/', 'The act of suspecting something or someone, especially of something wrong.', '懷疑、猜疑', 'https://api.dictionaryapi.dev/media/pronunciations/en/suspicion-us.mp3', 1, '2026-06-01 14:48:14'),
(5941, 'suspicious', 3, '/səˈspɪ.ʃəs/', 'Arousing suspicion.', '多疑的、可疑的、懷疑的', 'https://api.dictionaryapi.dev/media/pronunciations/en/suspicious-us.mp3', 1, '2026-06-01 14:48:14'),
(5942, 'swallow', 1, '/ˈswɒləʊ/', 'A deep chasm or abyss in the earth.', '燕子、吞嚥（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/swallow-us.mp3', 1, '2026-06-01 14:48:14'),
(5943, 'swallow', 2, '/ˈswɒləʊ/', 'To cause (food, drink etc.) to pass from the mouth into the stomach; to take into the stomach through the throat.', '吞嚥、侵吞、忍受', 'https://api.dictionaryapi.dev/media/pronunciations/en/swallow-us.mp3', 1, '2026-06-01 14:48:14'),
(5944, 'swan', 1, '/swɒn/', 'Any of various species of large, long-necked waterfowl, of genus Cygnus (bird family: Anatidae), most of which have white plumage.', '天鵝', 'https://api.dictionaryapi.dev/media/pronunciations/en/swan-us.mp3', 1, '2026-06-01 14:48:14'),
(5945, 'sway', 2, '/sweɪ/', 'To move or swing from side to side; or backward and forward; to rock.', '搖擺、搖晃、影響、支配', 'https://api.dictionaryapi.dev/media/pronunciations/en/sway-us.mp3', 1, '2026-06-01 14:48:14'),
(5946, 'swear', 2, '/swɛə/', 'To take an oath, to promise.', '發誓、宣誓、詛咒、罵人', 'https://api.dictionaryapi.dev/media/pronunciations/en/swear-us.mp3', 1, '2026-06-01 14:48:14'),
(5947, 'sweat', 1, '/swɛt/', 'Fluid that exits the body through pores in the skin usually due to physical stress and/or high temperature for the purpose of regulating body temperature and removing certain compounds from the circulation.', '汗、汗水（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/sweat-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5948, 'sweat', 2, '/swɛt/', 'Fluid that exits the body through pores in the skin usually due to physical stress and/or high temperature for the purpose of regulating body temperature and removing certain compounds from the circulation.', '出汗、流汗、焦慮（動詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/sweat-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5949, 'sweater', 1, '/ˈswetə/', 'A knitted jacket or jersey, usually of thick wool, worn by athletes before or after exercise.', '毛衣、針織衫', 'https://api.dictionaryapi.dev/media/pronunciations/en/sweater-us.mp3', 1, '2026-06-01 14:48:14'),
(5950, 'sweep', 1, '/swiːp/', 'A single action of sweeping.', '打掃、揮動、範圍（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/sweep-au.mp3', 1, '2026-06-01 14:48:14'),
(5951, 'sweep', 2, '/swiːp/', 'To clean (a surface) by means of a stroking motion of a broom or brush.', '打掃、席捲、橫掃、輕快地移動', 'https://api.dictionaryapi.dev/media/pronunciations/en/sweep-au.mp3', 1, '2026-06-01 14:48:14'),
(5952, 'sweet', 3, '/swiːt/', 'Having a pleasant taste, especially one relating to the basic taste sensation induced by sugar.', '甜的、芳香的、可愛的、悅耳的', 'https://api.dictionaryapi.dev/media/pronunciations/en/sweet-us.mp3', 1, '2026-06-01 14:48:14'),
(5953, 'swift', 3, '/swɪft/', 'Fast; quick; rapid.', '迅速的、敏捷的', 'https://api.dictionaryapi.dev/media/pronunciations/en/swift-us.mp3', 1, '2026-06-01 14:48:14'),
(5954, 'swim', 1, '/swɪm/', 'An act or instance of swimming.', '游泳、一陣眩暈（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/swim-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5955, 'swim', 2, '/swɪm/', 'To move through the water, without touching the bottom; to propel oneself in water by natural means.', '游泳、游過、游動', 'https://api.dictionaryapi.dev/media/pronunciations/en/swim-1-us.mp3', 1, '2026-06-01 14:48:14'),
(5956, 'swing', 1, '/ˈswɪŋ/', 'The manner in which something is swung.', '鞦韆、搖擺、擺動、音律（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/swing-au.mp3', 1, '2026-06-01 14:48:14'),
(5957, 'swing', 2, '/ˈswɪŋ/', 'To rotate about an off-centre fixed point.', '搖擺、擺動、旋轉、改變', 'https://api.dictionaryapi.dev/media/pronunciations/en/swing-au.mp3', 1, '2026-06-01 14:48:14'),
(5958, 'switch', 1, '/swɪtʃ/', 'A bundle of thin sticks, typically made of wood, sometimes bond in such a way that binding can be moved so that it varies the tightness of the binding.', '開關、電閘、轉換、鞭子（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/switch-us.mp3', 1, '2026-06-01 14:48:14'),
(5959, 'switch', 2, '/swɪtʃ/', 'To exchange.', '轉換、轉變、調換', 'https://api.dictionaryapi.dev/media/pronunciations/en/switch-us.mp3', 1, '2026-06-01 14:48:14'),
(5960, 'sword', 1, '/sɔːd/', 'A long-bladed weapon with a hilt, and usually a pommel and cross-guard, which is designed to stab, slash, and/or hack.', '劍、刀', 'https://api.dictionaryapi.dev/media/pronunciations/en/sword-us.mp3', 1, '2026-06-01 14:48:14'),
(5961, 'syllable', 1, '/ˈsɪləbəl/', 'A unit of human speech that is interpreted by the listener as a single sound, although syllables usually consist of one or more vowel sounds, either alone or combined with the sound of one or more consonants; a word consists of one or more syllables.', '音節', 'https://api.dictionaryapi.dev/media/pronunciations/en/syllable-uk.mp3', 1, '2026-06-01 14:48:14'),
(5962, 'syllabus', 1, '/ˈsɪləbəs/', 'A summary of topics which will be covered during an academic course, or a text or lecture.', '教學大綱、課程綱要', 'https://dictionaryapi.dev/syllabus', 1, '2026-06-01 14:48:14'),
(5963, 'symbol', 1, '/ˈsɪmbəl/', 'A character or glyph representing an idea, concept or object.', '象徵、符號、記號', 'https://api.dictionaryapi.dev/media/pronunciations/en/symbol-us.mp3', 1, '2026-06-01 14:48:14'),
(5964, 'symmetry', 1, '/ˈsɪmɪtɹi/', 'Exact correspondence on either side of a dividing line, plane, center or axis.', '對稱、對稱美', 'https://dictionaryapi.dev/symmetry', 1, '2026-06-01 14:48:14'),
(5965, 'sympathetic', 3, '/ˌsɪmpəˈθɛtɪk/', 'Of, related to, showing, or characterized by sympathy', '同情的、有同情心的、讚同的', 'https://api.dictionaryapi.dev/media/pronunciations/en/sympathetic-us.mp3', 1, '2026-06-01 14:48:14'),
(5966, 'sympathize', 2, '', 'To have, show or express sympathy; to be affected by feelings similar to those of another, in consequence of knowing the person to be thus affected.', '同情、憐憫、讚同', 'https://dictionaryapi.dev/sympathize', 1, '2026-06-01 14:48:14'),
(5967, 'sympathy', 1, '/ˈsɪmpəθi/', 'A feeling of pity or sorrow for the suffering or distress of another; compassion.', '同情心、憐憫、讚同、慰問', 'https://api.dictionaryapi.dev/media/pronunciations/en/sympathy-us.mp3', 1, '2026-06-01 14:48:14'),
(5968, 'symphony', 1, '/ˈsɪm.fə.ni/', 'An extended piece of music of sophisticated structure, usually for orchestra.', '交響樂、交響曲', 'https://dictionaryapi.dev/symphony', 1, '2026-06-01 14:48:14'),
(5969, 'synonym', 1, '/ˈsɪnənɪm/', '(strictly) A word whose meaning is the same as that of another word.', '同義字、同義詞', 'https://api.dictionaryapi.dev/media/pronunciations/en/synonym-us.mp3', 1, '2026-06-01 14:48:14'),
(5970, 'synthesis', 1, '/ˈsɪnθəsɪs/', 'The formation of something complex or coherent by combining simpler things.', '綜合、合成、綜合體', 'https://dictionaryapi.dev/synthesis', 1, '2026-06-01 14:48:14'),
(5971, 'system', 1, '', 'A collection of organized things; a whole composed of relationships among its members.', '系統、體系、制度、秩序', 'https://api.dictionaryapi.dev/media/pronunciations/en/system-au.mp3', 1, '2026-06-01 14:48:14'),
(5972, 'systematic', 3, '/ˌsɪs.təˈmæt.ɪk/', 'Carried out using a planned, ordered procedure.', '有系統的、有條理的、成體系的', 'https://api.dictionaryapi.dev/media/pronunciations/en/systematic-us.mp3', 1, '2026-06-01 14:48:14'),
(5973, 'systematically', 4, '', 'In an organized manner; utilising a system.', '系統地、有組織地、條理分明地', 'https://dictionaryapi.dev/systematically', 1, '2026-06-01 14:48:14'),
(5974, 'table', 1, '', 'Furniture with a top surface to accommodate a variety of uses.', '桌子、表格', 'https://api.dictionaryapi.dev/media/pronunciations/en/table-au.mp3', 1, '2026-06-01 14:48:14'),
(5975, 'tablespoon', 1, '', 'A large spoon, used for eating food from a bowl.', '大湯匙、一大湯匙的量', 'https://api.dictionaryapi.dev/media/pronunciations/en/tablespoon-au.mp3', 1, '2026-06-01 14:48:14'),
(5976, 'tablet', 1, '/ˈtæblət/', 'A slab of clay used for inscription.', '藥片、平板電腦、便條紙簿、匾額', 'https://dictionaryapi.dev/tablet', 1, '2026-06-01 14:48:14'),
(5977, 'tabloid', 1, '/ˈtæblɔɪd/', 'A newspaper having pages half the dimensions of the standard format.', '小報、八卦雜誌', '', 1, '2026-06-01 14:48:14'),
(5978, 'taboo', 1, '/tæˈbuː/', 'An inhibition or ban that results from social custom or emotional aversion.', '禁忌、忌諱', 'https://dictionaryapi.dev/taboo', 1, '2026-06-01 14:48:14'),
(5979, 'tackle', 2, '/ˈtækəl/', 'To force a person to the ground with the weight of one\'s own body, usually by jumping on top or slamming one\'s weight into him or her.', '處理、應付、扭獲、阻截（足球等）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tackle-us.mp3', 1, '2026-06-01 14:48:14'),
(5980, 'tag', 1, '/teɪɡ/', 'A small label.', '標籤、標牌、捉迷藏遊戲', 'https://api.dictionaryapi.dev/media/pronunciations/en/tag-1-au.mp3', 1, '2026-06-01 14:48:14'),
(5981, 'tail', 1, '/teɪl/', 'The caudal appendage of an animal that is attached to its posterior and near the anus.', '尾巴、尾部、後部', 'https://api.dictionaryapi.dev/media/pronunciations/en/tail-au.mp3', 1, '2026-06-01 14:48:14'),
(5982, 'tailor', 1, '/ˈteɪlə/', 'A person who makes, repairs, or alters clothes professionally, especially suits and men\'s clothing.', '裁縫師', 'https://api.dictionaryapi.dev/media/pronunciations/en/tailor-us.mp3', 1, '2026-06-01 14:48:14'),
(5983, 'take', 2, '/teɪk/', 'To get into one\'s hands, possession or control, with or without force.', '拿、帶走、花費（時間）、接受、搭乘', 'https://api.dictionaryapi.dev/media/pronunciations/en/take-au.mp3', 1, '2026-06-01 14:48:14'),
(5984, 'tale', 1, '/ˈteɪl/', 'An account of an asserted fact or circumstance; a rumour; a report, especially an idle or malicious story; a piece of gossip or slander; a lie.', '故事、傳說、敘述', 'https://api.dictionaryapi.dev/media/pronunciations/en/tale-au.mp3', 1, '2026-06-01 14:48:14'),
(5985, 'talent', 1, '/ˈtalənt/', 'A marked natural ability or skill.', '天才、才能、天資', 'https://api.dictionaryapi.dev/media/pronunciations/en/talent-us.mp3', 1, '2026-06-01 14:48:14'),
(5986, 'talkative', 3, '/ˈtɔːkətɪv/', 'Tending to talk a lot.', '健談的、多嘴的', 'https://dictionaryapi.dev/talkative', 1, '2026-06-01 14:48:14'),
(5987, 'tall', 3, '/tɔːl/', '(of a person) Having a vertical extent greater than the average. For example, somebody with a height of over 6 feet would generally be considered to be tall.', '高的、身材高大的', 'https://api.dictionaryapi.dev/media/pronunciations/en/tall-uk.mp3', 1, '2026-06-01 14:48:14'),
(5988, 'tally', 1, '/ˈtæli/', 'Target sighted.', '記帳、帳目、得分', 'https://api.dictionaryapi.dev/media/pronunciations/en/tally-1.mp3', 1, '2026-06-01 14:48:14'),
(5989, 'tally', 2, '/ˈtæli/', 'Target sighted.', '計算、點數、相符、符合', 'https://api.dictionaryapi.dev/media/pronunciations/en/tally-1.mp3', 1, '2026-06-01 14:48:14'),
(5990, 'tame', 3, '/teɪm/', 'Not or no longer wild; domesticated', '馴服的、溫順的、平淡的', 'https://api.dictionaryapi.dev/media/pronunciations/en/tame-us.mp3', 1, '2026-06-01 14:48:14'),
(5991, 'tan', 2, '/tæn/', 'A yellowish-brown colour.', '曬黑、把...曬成古銅色、鞣（革）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tan-uk.mp3', 1, '2026-06-01 14:48:14'),
(5992, 'tangible', 3, '/ˈtæn(d)ʒɪb(ə)l/', 'Touchable; able to be touched or felt; perceptible by the sense of touch', '可觸知的、有實體的、明確的', 'https://api.dictionaryapi.dev/media/pronunciations/en/tangible-us.mp3', 1, '2026-06-01 14:48:14'),
(5993, 'tank', 1, '/tæŋk/', 'A closed container for liquids or gases.', '大容器、槽、戰車、坦克', 'https://api.dictionaryapi.dev/media/pronunciations/en/tank-au.mp3', 1, '2026-06-01 14:48:14'),
(5994, 'tanker', 1, '', 'A tank ship, a vessel used to transport large quantities of liquid.', '油輪、油罐車', 'https://api.dictionaryapi.dev/media/pronunciations/en/tanker-au.mp3', 1, '2026-06-01 14:48:14'),
(5995, 'tap', 1, '/tæp/', 'A tapering cylindrical pin or peg used to stop the vent in a cask.', '水龍頭、輕拍、輕叩、竊聽（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tap-us.mp3', 1, '2026-06-01 14:48:14'),
(5996, 'tap', 2, '/tæp/', 'To furnish with taps.', '輕拍、輕叩、利用、開發、竊聽', 'https://api.dictionaryapi.dev/media/pronunciations/en/tap-us.mp3', 1, '2026-06-01 14:48:14'),
(5997, 'tape', 1, '/teɪ̯p/', 'Flexible material in a roll with a sticky surface on one or both sides; adhesive tape.', '膠帶、錄音帶、捲尺', 'https://api.dictionaryapi.dev/media/pronunciations/en/tape-us.mp3', 1, '2026-06-01 14:48:14'),
(5998, 'tape', 2, '/teɪ̯p/', 'To bind with adhesive tape.', '用膠帶捆綁、錄音、錄影', 'https://api.dictionaryapi.dev/media/pronunciations/en/tape-us.mp3', 1, '2026-06-01 14:48:14'),
(5999, 'target', 1, '', 'A butt or mark to shoot at, as for practice, or to test the accuracy of a firearm, or the force of a projectile.', '目標、靶子、對象', 'https://api.dictionaryapi.dev/media/pronunciations/en/target-au.mp3', 1, '2026-06-01 14:48:14'),
(6000, 'target', 2, '', 'To aim something, especially a weapon, at (a target).', '瞄準、以...為目標', 'https://api.dictionaryapi.dev/media/pronunciations/en/target-au.mp3', 1, '2026-06-01 14:48:14'),
(6001, 'tariff', 1, '/ˈtæɹəf/', 'A system of government-imposed duties levied on imported or exported goods; a list of such duties, or the duties themselves.', '關稅、收費表', 'https://dictionaryapi.dev/tariff', 1, '2026-06-01 14:48:14'),
(6002, 'task', 1, '/tɑːsk/', 'A piece of work done as part of one’s duties.', '任務、工作', 'https://api.dictionaryapi.dev/media/pronunciations/en/task-1-us.mp3', 1, '2026-06-01 14:48:14'),
(6003, 'taste', 1, '/teɪst/', 'One of the sensations produced by the tongue in response to certain chemicals; the quality of giving this sensation.', '味覺、味道、品味、愛好（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/taste-us.mp3', 1, '2026-06-01 14:48:14'),
(6004, 'taste', 2, '/teɪst/', 'To sample the flavor of something orally.', '嚐起來、品嚐、體驗（動詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/taste-us.mp3', 1, '2026-06-01 14:48:14'),
(6005, 'tasty', 3, '/ˈteɪsti/', 'Having a pleasant or satisfying flavor; delicious.', '美味的、可口的', 'https://api.dictionaryapi.dev/media/pronunciations/en/tasty-us.mp3', 1, '2026-06-01 14:48:14'),
(6006, 'tax', 1, '/tæks/', 'Money paid to the government other than for transaction-specific goods and services.', '稅、稅金（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tax-us.mp3', 1, '2026-06-01 14:48:14'),
(6007, 'tax', 2, '/tæks/', 'Money paid to the government other than for transaction-specific goods and services.', '向...課稅、使負重擔（動詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tax-us.mp3', 1, '2026-06-01 14:48:14'),
(6008, 'taxi', 1, '/ˈtæk.si/', 'A vehicle that may be hired for single journeys by members of the public, driven by a taxi driver.', '計程車', 'https://api.dictionaryapi.dev/media/pronunciations/en/taxi-uk.mp3', 1, '2026-06-01 14:48:14'),
(6009, 'tea', 1, '', 'A drug smoked or ingested for euphoric effect, cannabis.', '茶、茶葉', 'https://api.dictionaryapi.dev/media/pronunciations/en/tea-1-au.mp3', 1, '2026-06-01 14:48:14'),
(6010, 'teach', 2, '/tiːt͡ʃ/', 'To show (someone) the way; to guide, conduct; to point, indicate.', '教、教學、教導', 'https://api.dictionaryapi.dev/media/pronunciations/en/teach-us.mp3', 1, '2026-06-01 14:48:14'),
(6011, 'teacher', 1, '/ˈtiːt͡ʃə/', 'A person who teaches, especially one employed in a school.', '教師、老師', 'https://api.dictionaryapi.dev/media/pronunciations/en/teacher-uk.mp3', 1, '2026-06-01 14:48:14'),
(6012, 'team', 1, '/tiːm/', 'A set of draught animals, such as two horses in front of a carriage.', '隊、組、團隊', 'https://api.dictionaryapi.dev/media/pronunciations/en/team-us.mp3', 1, '2026-06-01 14:48:14'),
(6013, 'tear', 1, '', 'A hole or break caused by tearing.', '眼淚', 'https://dictionaryapi.dev/tear', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
(6014, 'technical', 3, '/ˈtɛk.nɪk.əl/', 'Of or pertaining to the useful or mechanic arts, or to any academic, legal, science, engineering, business, or the like terminology with specific and precise meaning or (frequently, as a degree of distinction) shades of meaning; specially appropriate to any art, science or engineering field, or business', '技術的、專門的、工業的', 'https://api.dictionaryapi.dev/media/pronunciations/en/technical-us.mp3', 1, '2026-06-01 14:48:14'),
(6015, 'technician', 1, '/tekˈnɪʃən/', 'A person who studies or practises technology.', '技術人員、技師', 'https://dictionaryapi.dev/technician', 1, '2026-06-01 14:48:14'),
(6016, 'technique', 1, '/tɛkˈniːk/', 'The practical aspects of a given art, occupation etc.; formal requirements.', '技術、技巧、技能', 'https://dictionaryapi.dev/technique', 1, '2026-06-01 14:48:14'),
(6017, 'technological', 3, '', 'Of, relating to, or involving technology, especially modern scientific technology.', '科技的、技術上的', 'https://dictionaryapi.dev/technological', 1, '2026-06-01 14:48:14'),
