(6191, 'tour', 1, '/tɔː(ɹ)/', 'A journey through a particular building, estate, country, etc.', '旅遊、參觀、巡迴演出（名詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tour-au.mp3', 1, '2026-06-01 14:48:14'),
(6192, 'tour', 2, '/tɔː(ɹ)/', 'To make a journey', '旅遊、遊覽、巡視（動詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/tour-au.mp3', 1, '2026-06-01 14:48:14'),
(6193, 'tourism', 1, '/tɔːɹɪz(ə)m/', 'The act of travelling or sightseeing, particularly away from one\'s home.', '觀光業、旅遊業', 'https://dictionaryapi.dev/tourism', 1, '2026-06-01 14:48:14'),
(6194, 'tourist', 1, '/ˈtʊəɹɪst/', 'Someone who travels for pleasure rather than for business.', '觀光客、遊客', 'https://dictionaryapi.dev/tourist', 1, '2026-06-01 14:48:14'),
(6195, 'tournament', 1, '/ˈtɔːnəmənt/', 'During the Middle Ages, a series of battles and other contests designed to prepare knights for war.', '錦標賽、聯賽、比賽', 'https://dictionaryapi.dev/tournament', 1, '2026-06-01 14:48:14'),
(6196, 'tow', 1, '', 'N/A', '拖、拉、牽引、拖車費（名詞）', NULL, 1, '2026-06-01 14:48:14'),
(6197, 'tow', 2, '', 'N/A', '拖、拉、牽引（動詞）', NULL, 1, '2026-06-01 14:48:14'),
(6198, 'toward', 5, '/tɘ.ˈwoːd/', 'In the direction of.', '向、朝著、對於（介系詞）', 'https://api.dictionaryapi.dev/media/pronunciations/en/toward-us.mp3', 1, '2026-06-01 14:48:14'),
(6199, 'towel', 1, '/taʊl/', 'A cloth used for wiping, especially one used for drying anything wet, as a person after a bath.', '毛巾、手巾', 'https://api.dictionaryapi.dev/media/pronunciations/en/towel-uk.mp3', 1, '2026-06-01 14:48:14'),
(6200, 'tower', 1, '/ˈtaʊ.ə(ɹ)/', 'A very tall iron-framed structure, usually painted red and white, on which microwave, radio, satellite, or other communication antennas are installed; mast.', '塔、高樓', 'https://api.dictionaryapi.dev/media/pronunciations/en/tower-1-us.mp3', 1, '2026-06-01 14:48:14'),
(6201, 'tower', 2, '/ˈtaʊ.ə(ɹ)/', 'A very tall iron-framed structure, usually painted red and white, on which microwave, radio, satellite, or other communication antennas are installed; mast.', '（高塔般）聳立、高出', 'https://api.dictionaryapi.dev/media/pronunciations/en/tower-1-us.mp3', 1, '2026-06-01 14:48:14'),
(6202, 'town', 1, '/taʊn/', 'A settlement; an area with residential districts, shops and amenities, and its own local government; especially one larger than a village and smaller than a city.', '城鎮、小鎮', 'https://api.dictionaryapi.dev/media/pronunciations/en/town-uk.mp3', 1, '2026-06-01 14:48:14'),
(6203, 'toxic', 3, '/ˈtɒk.sɪk/', 'Having a chemical nature that is harmful to health or lethal if consumed or otherwise entering into the body in sufficient quantities.', '有毒的、有害的', 'https://dictionaryapi.dev/toxic', 1, '2026-06-01 14:48:14'),
(6204, 'toy', 1, '/tɔɪ/', 'Something to play with, especially as intended for use by a child.', '玩具', 'https://api.dictionaryapi.dev/media/pronunciations/en/toy-us.mp3', 1, '2026-06-01 14:48:14'),
(6205, 'toy', 2, '/tɔɪ/', 'To play (with) in an idle or desultory way.', '玩弄、不認真對待', 'https://api.dictionaryapi.dev/media/pronunciations/en/toy-us.mp3', 1, '2026-06-01 14:48:14'),
(6206, 'trace', 1, '/tɹeɪs/', 'An act of tracing.', '痕跡、蹤跡、微量', 'https://api.dictionaryapi.dev/media/pronunciations/en/trace-us.mp3', 1, '2026-06-01 14:48:14'),
(6207, 'trace', 2, '/tɹeɪs/', 'An act of tracing.', '追蹤、描摹、查出', 'https://api.dictionaryapi.dev/media/pronunciations/en/trace-us.mp3', 1, '2026-06-01 14:48:14'),
(6208, 'track', 1, '/tɹæk/', 'A mark left by something that has passed along.', '軌道、跑道、蹤跡、樂曲', 'https://api.dictionaryapi.dev/media/pronunciations/en/track-au.mp3', 1, '2026-06-01 14:48:14'),
(6209, 'track', 2, '/tɹæk/', 'To continue over time.', '追蹤、跟蹤', 'https://api.dictionaryapi.dev/media/pronunciations/en/track-au.mp3', 1, '2026-06-01 14:48:14'),
(6210, 'tractor', 1, '/ˈtɹæktə/', 'A vehicle used in farms e.g. for pulling farm equipment and preparing the fields.', '拖拉機、牽引機', 'https://api.dictionaryapi.dev/media/pronunciations/en/tractor-us.mp3', 1, '2026-06-01 14:48:14'),
(6211, 'trade', 1, '/tɹeɪd/', 'Buying and selling of goods and services on a market.', '貿易、商業、行業', 'https://api.dictionaryapi.dev/media/pronunciations/en/trade-uk.mp3', 1, '2026-06-01 14:48:14'),
(6212, 'trade', 2, '/tɹeɪd/', 'To engage in trade.', '進行交易、交換、做買賣', 'https://api.dictionaryapi.dev/media/pronunciations/en/trade-uk.mp3', 1, '2026-06-01 14:48:14'),
(6213, 'tradition', 1, '/tɹəˈdɪʃn̩/', 'A part of culture that is passed from person to person or generation to generation, possibly differing in detail from family to family, such as the way to celebrate holidays.', '傳統、慣例', 'https://api.dictionaryapi.dev/media/pronunciations/en/tradition-us.mp3', 1, '2026-06-01 14:48:14'),
(6214, 'traditional', 3, '/tɹəˈdɪʃnəl/', 'Of, relating to, or derived from tradition.', '傳統的、慣例的', 'https://dictionaryapi.dev/traditional', 1, '2026-06-01 14:48:14'),
(6215, 'traffic', 1, '/ˈtɹæfɪk/', 'Pedestrians or vehicles on roads, or the flux or passage thereof.', '交通、交通量、買賣', 'https://api.dictionaryapi.dev/media/pronunciations/en/traffic-us.mp3', 1, '2026-06-01 14:48:14'),
(6216, 'tragedy', 1, '/ˈtɹæd͡ʒɪdi/', 'A drama or similar work, in which the main character is brought to ruin or otherwise suffers the extreme consequences of some tragic flaw or weakness of character.', '悲劇、慘劇', 'https://api.dictionaryapi.dev/media/pronunciations/en/tragedy-us.mp3', 1, '2026-06-01 14:48:14'),
