(6229, 'translation', 1, '/tɹæns-/', 'The act of translating, in its various senses:', '翻譯、譯文、譯本', 'https://api.dictionaryapi.dev/media/pronunciations/en/translation-uk.mp3', 1, '2026-06-01 14:48:14'),
(6230, 'translator', 1, '/ˈtɹanzleɪtə/', 'A person who translates text, film or other material into a different natural language.', '翻譯員、譯者', 'https://api.dictionaryapi.dev/media/pronunciations/en/translator-uk.mp3', 1, '2026-06-01 14:48:14'),
(6231, 'transmission', 1, '/tɹænsˈmɪʃən/', 'The act of transmitting, e.g. data or electric power.', '傳播、傳送、變速箱', 'https://dictionaryapi.dev/transmission', 1, '2026-06-01 14:48:14'),
