(6251, 'trespass', 2, '/ˈtɹɛspəs/', 'An intentional interference with another\'s property or person.', '擅自進入、侵入（他人土地）', 'https://api.dictionaryapi.dev/media/pronunciations/en/trespass-uk.mp3', 1, '2026-06-01 14:48:14'),
(6252, 'trial', 1, '/ˈtɹaɪəl/', 'An opportunity to test something out; a test.', '審判、試驗、考驗', 'https://api.dictionaryapi.dev/media/pronunciations/en/trial-us.mp3', 1, '2026-06-01 14:48:14'),
(6253, 'triangle', 1, '/ˈtɹaɪəŋɡəl/', 'A polygon with three sides and three angles.', '三角形', 'https://api.dictionaryapi.dev/media/pronunciations/en/triangle-us.mp3', 1, '2026-06-01 14:48:14'),
(6254, 'tribe', 1, '/tɹaɪb/', 'A socially, ethnically, or politically cohesive group of people.', '部落、氏族', 'https://api.dictionaryapi.dev/media/pronunciations/en/tribe-us.mp3', 1, '2026-06-01 14:48:14'),
(6255, 'tribune', 1, '/tɹɪˈbjuːn/', 'An elected official in Ancient Rome.', '論壇、演講台、（報紙名稱常用）論壇報', 'https://dictionaryapi.dev/tribune', 1, '2026-06-01 14:48:14'),
(6256, 'trick', 1, '/tɹɪk/', 'Something designed to fool or swindle.', '惡作劇、把戲、計謀、訣竅', 'https://api.dictionaryapi.dev/media/pronunciations/en/trick-us.mp3', 1, '2026-06-01 14:48:14'),
(6257, 'trick', 2, '/tɹɪk/', 'To fool; to cause to believe something untrue; to deceive.', '欺騙、哄騙', 'https://api.dictionaryapi.dev/media/pronunciations/en/trick-us.mp3', 1, '2026-06-01 14:48:14'),
(6258, 'tricky', 3, '/tɹɪki/', 'Hard to deal with, complicated', '棘手的、難辦的、狡猾的', 'https://api.dictionaryapi.dev/media/pronunciations/en/tricky-us.mp3', 1, '2026-06-01 14:48:14'),
(6259, 'trigger', 1, '/ˈtɹɪɡə/', 'A finger-operated lever used to fire a gun.', '（槍的）扳機、觸發器', 'https://dictionaryapi.dev/trigger', 1, '2026-06-01 14:48:14'),
(6260, 'trigger', 2, '/ˈtɹɪɡə/', 'To fire a weapon.', '觸發、引起、引發', 'https://dictionaryapi.dev/trigger', 1, '2026-06-01 14:48:14'),
(6261, 'trim', 2, '/tɹɪm/', 'To reduce slightly; to cut; especially, to remove excess.', '修剪、修整、削減', 'https://api.dictionaryapi.dev/media/pronunciations/en/trim-us.mp3', 1, '2026-06-01 14:48:14');
INSERT INTO `words` (`id`, `word`, `part_of_speech_id`, `phonetic`, `definition`, `translation`, `audio_url`, `source`, `created_at`) VALUES
