(6266, 'trivial', 3, '/ˈtɹɪ.vi.əl/', 'Ignorable; of little significance or value.', '微不足道的、瑣碎的', 'https://api.dictionaryapi.dev/media/pronunciations/en/trivial-us.mp3', 1, '2026-06-01 14:48:14'),
(6267, 'troop', 1, '/tɹuːp/', '(collective) A collection of people; a number; a multitude (in general).', '軍隊、部隊、一群', 'https://api.dictionaryapi.dev/media/pronunciations/en/troop-uk.mp3', 1, '2026-06-01 14:48:14'),
(6268, 'trophy', 1, '/ˈtɹəʊfi/', 'Tropæum.', '獎盃、獎牌', 'https://api.dictionaryapi.dev/media/pronunciations/en/trophy-uk.mp3', 1, '2026-06-01 14:48:14'),
(6269, 'tropical', 3, '', 'Of or pertaining to the tropics, the equatorial region between 23 degrees north and 23 degrees south.', '熱帶的', 'https://dictionaryapi.dev/tropical', 1, '2026-06-01 14:48:14'),
(6270, 'trouble', 1, '/ˈtɹʌb(ə)l/', 'A distressing or dangerous situation.', '麻煩、困難、煩惱', 'https://api.dictionaryapi.dev/media/pronunciations/en/trouble-us.mp3', 1, '2026-06-01 14:48:14'),
(6271, 'trouble', 2, '/ˈtɹʌb(ə)l/', 'To disturb, stir up, agitate (a medium, especially water).', '麻煩、使煩惱、勞駕', 'https://api.dictionaryapi.dev/media/pronunciations/en/trouble-us.mp3', 1, '2026-06-01 14:48:14'),
(6272, 'troublesome', 3, '/ˈtɹʌbl̩səm/', 'Causing trouble or anxiety', '麻煩的、令人討厭的', 'https://api.dictionaryapi.dev/media/pronunciations/en/troublesome-us.mp3', 1, '2026-06-01 14:48:14'),
(6273, 'trousers', 1, '', 'An article of clothing that covers the part of the body between the waist and the ankles or knees, and is divided into a separate part for each leg.', '長褲、褲子', 'https://api.dictionaryapi.dev/media/pronunciations/en/trousers-au.mp3', 1, '2026-06-01 14:48:14'),
(6274, 'truck', 1, '/tɹʌk/', 'A small wheel or roller, specifically the wheel of a gun carriage.', '卡車、貨車', 'https://api.dictionaryapi.dev/media/pronunciations/en/truck-au.mp3', 1, '2026-06-01 14:48:14'),
(6275, 'truck', 2, '/tɹʌk/', 'To drive a truck: Generally a truck driver\'s slang.', '用卡車運送', 'https://api.dictionaryapi.dev/media/pronunciations/en/truck-au.mp3', 1, '2026-06-01 14:48:14'),
